insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ الْمُسْلِمُونَ حِينَ قَدِمُوا الْمَدِينَةَ يَجْتَمِعُونَ فَيَتَحَيَّنُونَ الصَّلَاةَ لَيْسَ يُنَادَى لَهَا، فَتَكَلَّمُوا يَوْمًا فِي ذَلِكَ فَقَالَ بَعْضُهُمْ: اتَّخِذُوا نَاقُوسًا مِثْلَ نَاقُوسِ النَّصَارَى، وَقَالَ بَعْضُهُمْ: بَلْ بُوقًا مِثْلَ قَرْنِ الْيَهُودِ، فَقَالَ عُمَرُ: أَوَلَا تَبْعَثُونَ رَجُلًا يُنَادِي بِالصَّلَاةِ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا بِلَالُ قُمْ فَنَادِ بِالصَّلَاةِ". (ق,ت,ن)', 'ഇബ്നുഉമർ(റ): മുസ്ലിംകൾ മദീനയിൽ ചെന്ന കാലത്ത് നിസ്കാരസമയം അവർ പരസ്പരം ആലോചിച്ചു നിർണ്ണയിക്കുകയായിരുന്നു പതിവ്. അന്ന് ബാങ്ക് വിളിക്കാറുണ്ടായിരുന്നില്ല. അവർ അക്കാര്യത്തെക്കുറിച്ച് ഒരു ദിവസം ചർച്ച ചെയ്തു. ചിലർ നിർദ്ദേശിച്ചു: ക്രിസ്ത്യാനികളെപ്പോലെ മണിയടിക്കാം. ചിലർ പറഞ്ഞു: ജൂതന്മാരെപ്പോലെ കുഴലൂതാം. അപ്പോൾ ഉമർ(റ) ചോദിച്ചു: നിസ്കാരത്തിനു വേണ്ടി വിളിക്കാൻ നമുക്കൊരാളെ നിയോഗിച്ചുകൂടേ? നബി(സ) പറഞ്ഞു: "ബിലാൽ, നീ എഴുന്നേറ്റ് നിസ്കാരത്തിന് വിളിക്കു." (ബു,മു,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 285, 285, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي عُمَيْرِ بْنِ أَنَسٍ رَضِيَ اللهُ عَنْهُمَا عَنْ عُمُومَةٍ لَهُ مِنَ الْأَنْصَارِ قَالَ: اهْتَمَّ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلصَّلَاةِ، كَيْفَ يَجْمَعُ النَّاسَ لَهَا؟ فَقِيلَ لَهُ: انْصِبْ رَايَةً عِنْدَ حُضُورِ الصَّلَاةِ، فَإِذَا رَأَوْهَا آذَنَ بَعْضُهُمْ بَعْضًا، فَلَمْ يُعْجِبْهُ ذَلِكَ. قَالَ: فَذُكِرَ لَهُ الْقُنْعُ – يَعْنِي الشَّبُّورَ وَقَالَ زِيَادٌ شَبُّورُ الْيَهُودِ – فَلَمْ يُعْجِبْهُ ذَلِكَ، وَقَالَ: "هُوَ مِنْ أَمْرِ الْيَهُودِ". قَالَ: فَذُكِرَ لَهُ النَّاقُوسُ، فَقَالَ: "هُوَ مِنْ أَمْرِ النَّصَارَى". فَانْصَرَفَ عَبْدُ اللهِ بْنُ زَيْدِ بْنِ عَبْدِ رَبِّهِ وَهُوَ مُهْتَمٌّ لِهَمِّ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأُرِيَ الْأَذَانَ فِي مَنَامِهِ، قَالَ: فَغَدَا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ، فَقَالَ لَهُ: يَا رَسُولَ اللهِ، إِنِّي لَبَيْنَ نَائِمٍ وَيَقْظَانَ إِذْ أَتَانِي آتٍ فَأَرَانِي الْأَذَانَ، قَالَ: وَكَانَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَدْ رَآهُ قَبْلَ ذَلِكَ فَكَتَمَهُ عِشْرِينَ يَوْمًا، قَالَ: ثُمَّ أَخْبَرَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُ: "مَا مَنَعَكَ أَنْ تُخْبِرَنِي". فَقَالَ: سَبَقَنِي عَبْدُ اللهِ بْنُ زَيْدٍ، فَاسْتَحْيَيْتُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا بِلَالُ، قُمْ فَانْظُرْ مَا يَأْمُرُكَ بِهِ عَبْدُ اللهِ بْنُ زَيْدٍ فَافْعَلْهُ". قَالَ: فَأَذَّنَ بِلَالٌ. (د)', 'അബീഉമൈറുബ്നു അനസുബ്നു മാലിക്(റ): അൻസാറുകളിൽപെട്ട തന്റെ പിതൃസഹോദരനിൽ നിന്ന്: നിസ്കാരത്തിന്വേണ്ടി ജനങ്ങളെ എപ്രകാരം ഒരുമിച്ചുകൂട്ടും എന്ന കാര്യത്തിൽ നബി(സ) അഭിപ്രായമാരാഞ്ഞപ്പോൾ ചിലർ പറഞ്ഞു: നിസ്കാര സമയമാകുമ്പോൾ ഒരു കൊടി നാട്ടാം. അതുകാണുമ്പോൾ അവർ പരസ്പരം നിസ്കാരത്തെക്കുറിച്ചുണർത്തട്ടെ. ആ അഭിപ്രായം നബിക്കു തൃപ്തികരമായില്ല. യഹൂദരെപ്പോലെ കാഹളമൂതുന്നതിനെക്കുറിച്ച് പറഞ്ഞപ്പോൾ അതും തൃപ്തികരമായില്ല. നബി(സ) പറഞ്ഞു: "അത് യഹൂദികളുടെ ആചാരമാണ്." മണിയടിക്കുന്നതിനെക്കുറിച്ച് പറഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് ക്രിസ്ത്യാനികളുടെ ആചാരമാണ്." തുടർന്ന് അബ്ദുല്ലാഹിബ്നു സൈദുബ്നു അബ്ദുറബ്ബ് നബിയുടെ ആലോചനയെക്കുറിച്ച് വ്യാകുലനായി മടങ്ങി. അദ്ദേഹം ബാങ്കിന്റെ വചനങ്ങൾ സ്വപ്നത്തിൽ ദർശിക്കുകയും തിരുസന്നിധിയിൽ ചെന്ന് ഇപ്രകാരം അറിയിക്കുകയും ചെയ്തു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാൻ ഉറക്കത്തിനും ഉണർച്ചക്കും ഇടയിലായിരിക്കെ ഒരാൾ വന്ന് എനിക്കു ബാങ്ക് (വിളിച്ചു) കാണിച്ചുതന്നു. ഉമറി(റ)നും ഇപ്രകാരം ദർശനമുണ്ടാവുകയും അദ്ദേഹം ഇരുപത് ദിവസം അതു മറച്ചു വെക്കുകയും ചെയ്തു. പിന്നീടതിനെക്കുറിച്ച് പറഞ്ഞപ്പോൾ "എന്തുകൊണ്ടാണ് താങ്കൾ അത് പറയാതിരുന്നത്" എന്ന് നബി(സ) ചോദിച്ചപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അബ്ദുല്ലാഹിബ്നു സൈദ് എന്നെ മുൻകടന്നതിനാൽ എനിക്ക് ലജ്ജ തോന്നിയതാണ്. നബി(സ) ബിലാലിനോടായി പറഞ്ഞു. "നിന്നോട് അബ്ദുല്ലാഹിബ്നു സൈദ് എന്താണോ നിർദ്ദേശിക്കുന്നത് അപ്രകാരം ചെയ്യുക." അങ്ങനെ ബിലാൽ(റ) ബാങ്ക് വിളിച്ചു. (ദ)', 'أَبِي عُمَيْرِ بْنِ أَنَسٍ', 'അബീഉമൈറുബ്നു അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 285, 286, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عَبْدِ اللهِ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ هَمَّ بِالْبُوقِ، وَأَمَرَ بِالنَّاقُوسِ فَنُحِتَ، فَأُرِيَ عَبْدُ اللهِ بْنُ زَيْدٍ فِي الْمَنَامِ، قَالَ: رَأَيْتُ رَجُلًا عَلَيْهِ ثَوْبَانِ أَخْضَرَانِ، يَحْمِلُ نَاقُوسًا، فَقُلْتُ لَهُ: يَا عَبْدَ اللهِ تَبِيعُ النَّاقُوسَ؟ قَالَ: وَمَا تَصْنَعُ بِهِ؟ قُلْتُ: أُنَادِي بِهِ إِلَى الصَّلَاةِ. قَالَ: أَفَلَا أَدُلُّكَ عَلَى خَيْرٍ مِنْ ذَلِكَ؟ قُلْتُ: وَمَا هُوَ؟ قَالَ تَقُولُ: اللهُ أَكْبَرُ، اللهُ أَكْبَرُ، اللهُ أَكْبَرُ، اللهُ أَكْبَرُ. أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ. حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الصَّلَاةِ. حَيَّ عَلَى الْفَلَاحِ، حَيَّ عَلَى الْفَلَاحِ. اللهُ أَكْبَرُ، اللهُ أَكْبَرُ. لَا إِلَهَ إِلَّا اللهُ. قَالَ: فَخَرَجَ عَبْدُ اللهِ بْنُ زَيْدٍ حَتَّى أَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ بِمَا رَأَى، قَالَ: يَا رَسُولَ اللهِ، رَأَيْتُ رَجُلًا عَلَيْهِ ثَوْبَانِ أَخْضَرَانِ، يَحْمِلُ نَاقُوسًا ... فَقَصَّ عَلَيْهِ الْخَبَرَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ صَاحِبَكُمْ قَدْ رَأَى رُؤْيَا"، فَاخْرُجْ مَعَ بِلَالٍ إِلَى الْمَسْجِدِ، فَأَلْقِهَا عَلَيْهِ، وَلْيُنَادِ بِلَالٌ، فَإِنَّهُ أَنْدَى صَوْتًا مِنْكَ". قَالَ: فَخَرَجْتُ مَعَ بِلَالٍ إِلَى الْمَسْجِدِ، فَجَعَلْتُ أُلْقِيهَا عَلَيْهِ وَهُوَ يُنَادِي بِهَا، فَسَمِعَ عُمَرُ بْنُ الْخَطَّابِ بِالصَّوْتِ فَخَرَجَ، فَقَالَ: يَا رَسُولَ اللهِ، وَاللهِ لَقَدْ رَأَيْتُ مِثْلَ الَّذِي رَأَى، قَالَ أَبُو عُبَيْدٍ: فَأَخْبَرَنِي أَبُو بَكْرٍ الْحَكَمِيُّ أَنَّ عَبْدَ اللهِ بْنَ زَيْدٍ الْأَنْصَارِيَّ قَالَ فِي ذَلِكَ:
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَبْدِ اللهِ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا أَصْبَحْنَا أَتَيْنَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ بِالرُّؤْيَا، فَقَالَ: "إِنَّ هَذِهِ لَرُؤْيَا حَقٌّ، فَقُمْ مَعَ بِلَالٍ، فَإِنَّهُ أَنْدَى وَأَمَدُّ صَوْتًا مِنْكَ، فَأَلْقِ عَلَيْهِ مَا قِيلَ لَكَ، وَلْيُنَادِ بِذَلِكَ". قَالَ: فَلَمَّا سَمِعَ عُمَرُ بْنُ الْخَطَّابِ نِدَاءَ بِلَالٍ بِالصَّلَاةِ خَرَجَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَجُرُّ إِزَارَهُ وَهُوَ يَقُولُ: يَا رَسُولَ اللهِ، وَالَّذِي بَعَثَكَ بِالْحَقِّ، لَقَدْ رَأَيْتُ مِثْلَ الَّذِي قَالَ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَلِلَّهِ الْحَمْدُ، فَذَلِكَ أَثْبَتُ". (د,ن)', 'അബ്ദുല്ലാഹിബ്നു സൈദ്(റ): പ്രഭാതമായപ്പോൾ തിരുസന്നിധിയിൽ ചെന്ന് ഞാൻ സ്വപ്നത്തെക്കുറിച്ച് അറിയിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിശ്ചയം, ഇത് യാഥാർത്ഥ്യമാണ്. നീ ബിലാലിനോടൊപ്പം പോവുക. നിന്നെക്കാൾ ഉയർന്നതും ഗാംഭീര്യമുള്ളതുമായ ശബ്ദത്തിന്റെ ഉടമയാണ് ബിലാൽ. നിന്നോട് പറയപ്പെട്ടത് ബിലാലിന്ന് പറഞ്ഞുകൊടുക്കുക. ബിലാൽ അത് വിളിച്ചു പറയട്ടെ". ബിലാലി(റ)ന്റെ ബാങ്കുകേട്ട് തന്റെ തുണി വലിച്ചുപിടിച്ചു കൊണ്ട് ഉറക്കിൽ നിന്നുണർന്ന് ഉമർ(റ) ഇറങ്ങിവന്ന് നബി(സ)യോട് പറഞ്ഞു: സത്യവാക്യവുമായി താങ്കളെ നിയോഗിച്ചവനാണെ! ഇപ്രകാരം ഞാനും കണ്ടിട്ടുണ്ട്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്നു സ്തുതി. ഇതാണ് ഏറ്റവും സ്ഥിരപ്പെട്ടത്." (ദ,ന)', 'عَبْدِ اللهِ بْنِ زَيْدٍ', 'അബ്ദുല്ലാഹിബ്നു സൈദ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 287, 287, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنِ ابن عمر رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اسْتَشَارَ النَّاسَ لِمَا يُهِمُّهُمْ إِلَى الصَّلَاةِ، فَذَكَرُوا الْبُوقَ، فَكَرِهَهُ مِنْ أَجْلِ الْيَهُودِ. ثُمَّ ذَكَرُوا النَّاقُوسَ، فَكَرِهَهُ مِنْ أَجْلِ النَّصَارَى. فَأُرِيَ النِّدَاءَ تِلْكَ اللَّيْلَةَ رَجُلٌ مِنَ الْأَنْصَارِ يُقَالُ لَهُ عَبْدُ اللهِ بْنُ زَيْدٍ، وَعُمَرُ بْنُ الْخَطَّابِ. فَطَرَقَ الْأَنْصَارِيُّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيْلًا، فَأَمَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِلَالًا بِهِ، فَأَذَّنَ. (جه)', 'ഇബ്നുഉമർ(റ): നിസ്കാരത്തിന് വിളിക്കുന്നതിനെക്കുറിച്ച് നബി(സ) ജനങ്ങളുമായി കൂടിയാലോചന നടത്തി. കുഴലൂത്ത് നടത്താമെന്ന് ചിലർ പറഞ്ഞു. യഹൂദികളുടെ ആചാരമാകയാൽ പ്രവാചകൻ അതിനെ വെറുത്തു. മണിയടിക്കാമെന്ന് ചിലർ പറഞ്ഞു. ക്രിസ്ത്യാനികളുടെ ആചാരമായതിനാൽ പ്രവാചകൻ അതിനെയും വെറുത്തു. അന്നുരാത്രി അൻസാരികളിൽപെട്ട അബ്ദുല്ലാഹിബ്നു സൈദ് ബാങ്ക് സ്വപ്നത്തിൽ കണ്ടു. ഉമറും(റ) അപ്രകാരം കണ്ടിരുന്നു. അൻസാരി രാത്രി തന്നെ പ്രവാചക സന്നിധിയിലെത്തി. വാതിലിൽ മുട്ടിവിളിച്ചു. നബി(സ) ബിലാലിനെ ബാങ്ക് വിളിക്കാൻ ഏല്പിച്ചു. അങ്ങനെ ബിലാൽ(റ) ബാങ്ക് വിളിച്ചു. (ജ)', 'ابن عمر', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 287, 287, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَبِي مَحْذُورَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ نَبِيَّ اللهِ عَلَّمَهُ هَذَا الْأَذَانَ: "اللهُ أَكْبَرُ اللهُ أَكْبَرُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ – ثُمَّ يَعُودُ فَيَقُولُ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، حَيَّ عَلَى الصَّلَاةِ – مَرَّتَيْنِ – حَيَّ عَلَى الْفَلَاحِ – مَرَّتَيْنِ زَادَ إِسْحَقُ: اللهُ أَكْبَرُ، اللهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللهُ". (م)', 'അബൂമഹ്ദൂറ(റ): നബി(സ) അദ്ദേഹത്തെ ഇപ്രകാരം ബാങ്ക് പഠിപ്പിച്ചു: "അല്ലാഹു അക്ബർ അല്ലാഹു അക്ബർ (അല്ലാഹു ഏറ്റവും വലിയവൻ). അശ്ഹദു അൻലാ ഇലാഹ ഇല്ലല്ലാഹ് (അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല എന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു) അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാഹ് (മുഹമ്മദ് അല്ലാഹുവിന്റെ ദൂതനാകുന്നു എന്നു ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു) പിന്നെ ആവർത്തിച്ചു ഇപ്രകാരം പറഞ്ഞു: അശ്ഹദു അൻലാ ഇലാഹ ഇല്ലല്ലാഹ്, അശ്ഹദു അൻലാ ഇലാഹ ഇല്ലല്ലാഹ്. അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാഹ്, അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാഹ്. ഹയ്യഅലസ്സ്വലാഃ, ഹയ്യ അലസ്സ്വലാഃ (നിസ്കാരത്തിനു വരിക). ഹയ്യഅലൽ ഫലാഹ്, ഹയ്യഅലൽ ഫലാഹ് (വിജയത്തിലേക്ക് വരിക)
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي مَحْذُورَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَقْعَدَهُ فَأَلْقَى عَلَيْهِ الْأَذَانَ حَرْفًا حَرْفًا (ت,ن)', 'അബൂമഹ്ദൂറ(റ): നബി(സ) അദ്ദേഹത്തെ ഇരുത്തി ബാങ്ക് പദാനുപദമായി പഠിപ്പിച്ചു. (തു,ന)', 'أَبِي مَحْذُورَةَ', 'അബൂമഹ്ദൂറ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 288, 288, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عن أبي مَحْذُورَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَّمَهُ الْأَذَانَ تِسْعَ عَشْرَةَ كَلِمَةً، وَالْإِقَامَةَ سَبْعَ عَشْرَةَ كَلِمَةً (ت,ن)', 'അബൂമഹ്ദൂറ(റ): നബി(സ) അദ്ദേഹത്തെ പത്തൊൻപത് പദങ്ങളായി ബാങ്ക് പഠിപ്പിച്ചു. പതിനേഴു പദങ്ങളായി ഇഖാമത്തും പഠിപ്പിച്ചു. (തു,ന)', 'أبي مَحْذُورَةَ', 'അബൂമഹ്ദൂറ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 288, 288, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عن أبي مَحْذُورَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ! عَلِّمْنِي سُنَّةَ الْأَذَانِ، قَالَ: فَمَسَحَ مُقَدَّمَ رَأْسِي وَقَالَ: "تَقُولُ: اللهُ أَكْبَرُ، اللهُ أَكْبَرُ، اللهُ أَكْبَرُ، اللهُ أَكْبَرُ، تَرْفَعُ بِهَا صَوْتَكَ ثُمَّ تَقُولُ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، تَخْفِضُ بِهَا صَوْتَكَ ثُمَّ تَرْفَعُ صَوْتَكَ بِالشَّهَادَةِ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الْفَلَاحِ، حَيَّ عَلَى الْفَلَاحِ، فَإِنْ كَانَ صَلَاةُ الصُّبْحِ قُلْتَ: الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ، الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ، – وَفِي رِوَايَةٍ: فِي الْأُولَى مِنَ الصُّبْحِ – اللهُ أَكْبَرُ، اللهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللهُ (م,د,ت,ن,جه)', 'അബൂമഹ്ദൂറ(റ): ഞാൻ നബി(സ)യോട് പറഞ്ഞു: എനിക്കു ബാങ്കിന്റെ സുന്നത്തുകൾ പഠിപ്പിച്ചു തന്നാലും! എന്റെ തലയിൽ തലോടിക്കൊണ്ടു നബി(സ) പറഞ്ഞു: "നീ ഇപ്രകാരം പറയുക: അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ. അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ. അതു പറയുമ്പോൾ നീ ശബ്ദമുയർത്തുക. പിന്നെ നീ ഇപ്രകാരം പറയുക: അശ്ഹദു അൻലാ ഇലാഹ ഇല്ലല്ലാഹ്, അശ്ഹദു അൻല്ലാ ഇലാഹ ഇല്ലല്ലാഹ്. അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാഹ്, അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാഹ്. ഇതു പറയുമ്പോൾ നീ ശബ്ദം താഴ്ത്തുക. പിന്നെ ശബ്ദം ഉയർത്തിക്കൊണ്ട് ശഹാദത്ത് ഇപ്രകാരം പറയുക: അശ്ഹദു അൻലാ ഇലാഹ ഇല്ലല്ലാഹ്, അശ്ഹദു അൻലാ ഇലാഹ ഇല്ലല്ലാഹ്. അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാഹ്, അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാഹ്. ഹയ്യ അലസ്സ്വലാഃ, ഹയ്യ അലസ്സ്വലാഃ. ഹയ്യ അലൽ ഫലാഹ്, ഹയ്യ അലൽ ഫലാഹ്. സുബ്ഹി നിസ്കാരത്തിനു വേണ്ടിയാണെങ്കിൽ നീ ഇപ്രകാരം കൂടി പറയുക: അസ്സ്വലാതു ഖൈറുമ്മിനന്നൗം (നിസ്കാരം ഉറക്കത്തേക്കാൾ ഉത്തമമാകുന്നു) അസ്സ്വലാതു ഖൈറുമ്മിനന്നൗം. മറ്റൊരു റിപ്പോർട്ടിൽ: ''അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ, ലാഇലാഹ ഇല്ലല്ലാഹു'' എന്നുമുണ്ട്. (മു,ദ,തു,ന,ജ)', 'أبي مَحْذُورَةَ', 'അബൂമഹ്ദൂറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 288, 288, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=15 and h.hadith_no=9), 1, 'وَفِي رِوَايَةٍ: فِي الْأُولَى مِنَ الصُّبْحِ – اللهُ أَكْبَرُ، اللهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللهُ (م,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: ''അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ, ലാഇലാഹ ഇല്ലല്ലാഹു'' എന്നുമുണ്ട്. (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنِ ابْنِ أَبِي لَيْلَى رَضِيَ اللهُ عَنْهُ قَالَ: أُحِيلَتِ الصَّلَاةُ ثَلَاثَةَ أَحْوَالٍ، قَالَ: وَحَدَّثَنَا أَصْحَابُنَا أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَقَدْ أَعْجَبَنِي أَنْ تَكُونَ صَلَاةُ الْمُسْلِمِينَ – أَوْ قَالَ الْمُؤْمِنِينَ – وَاحِدَةً، حَتَّى لَقَدْ هَمَمْتُ أَنْ أَبُثَّ رِجَالًا فِي الدُّورِ يُنَادُونَ النَّاسَ بِحِينِ الصَّلَاةِ، وَحَتَّى هَمَمْتُ أَنْ آمُرَ رِجَالًا يَقُومُونَ عَلَى الْآطَامِ يُنَادُونَ الْمُسْلِمِينَ بِحِينِ الصَّلَاةِ، حَتَّى نَقَسُوا أَوْ كَادُوا أَنْ يَنْقُسُوا". قَالَ: فَجَاءَ رَجُلٌ مِنَ الْأَنْصَارِ فَقَالَ: يَا رَسُولَ اللهِ! إِنِّي لَمَّا رَجَعْتُ لِمَا رَأَيْتُ مِنِ اهْتِمَامِكَ رَأَيْتُ رَجُلًا كَأَنَّ عَلَيْهِ ثَوْبَيْنِ أَخْضَرَيْنِ، فَقَامَ عَلَى الْمَسْجِدِ، فَأَذَّنَ ثُمَّ قَعَدَ قَعْدَةً، ثُمَّ قَامَ فَقَالَ مِثْلَهَا إِلَّا أَنَّهُ يَقُولُ: قَدْ قَامَتِ الصَّلَاةُ، وَلَوْلَا أَنْ يَقُولَ النَّاسُ لَقُلْتُ: إِنِّي كُنْتُ يَقْظَانَ غَيْرَ نَائِمٍ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَقَدْ أَرَاكَ اللهُ عَزَّ وَجَلَّ خَيْرًا، فَمُرْ بِلَالًا فَلْيُؤَذِّنْ". قَالَ: فَقَالَ عُمَرُ: أَمَا إِنِّي قَدْ رَأَيْتُ مِثْلَ الَّذِي رَأَى، وَلَكِنِّي لَمَّا سُبِقْتُ اسْتَحْيَيْتُ، قَالَ: وَحَدَّثَنَا أَصْحَابُنَا قَالُوا: وَكَانَ الرَّجُلُ إِذَا جَاءَ يَسْأَلُ فَيُخْبَرُ بِمَا سُبِقَ مِنْ صَلَاتِهِ، وَإِنَّهُمْ قَامُوا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ بَيْنِ قَائِمٍ وَرَاكِعٍ وَقَاعِدٍ وَمُصَلٍّ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'ഇബ്നുഅബീലൈല(റ): നിസ്കാരം (അതിലേക്ക് വിളിക്കൽ) മൂന്ന് അവസ്ഥകൾ തരണംചെയ്തു. ഞങ്ങളോട് ഞങ്ങളുടെ കൂട്ടുകാർ പറഞ്ഞു: നബി(സ) പറഞ്ഞു: "മുസ്ലിംകളുടെ -വിശ്വാസികളുടെ - നിസ്കാരം ഒരേ സമയത്തായിത്തീരുക എന്നത് എന്നെ സന്തോഷിപ്പിക്കുന്നതാണ്." നിസ്കാരത്തിനു വിളിക്കാനായി കുറേ ആളുകളെ ഓരോ ഭാഗത്തേക്കും അയക്കുകയോ ഉയർന്ന വീടുകളുടെ മുകളിൽ കയറ്റിനിർത്തുകയോ ചെയ്താലോ എന്നു ഞാൻ കരുതി. അങ്ങനെ അവർ മണിയടി ഏർപ്പെടുത്തുന്നിടത്തോളം കാര്യം എത്താറായി. അപ്പോൾ അൻസ്വാറുകളിൽപ്പെട്ട ഒരാൾ വന്നു പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, താങ്കളുടെ അടുത്തു നിന്ന് തിരിച്ചുപോയശേഷം പച്ച വസ്ത്രം ധരിച്ച ഒരാളെ ഞാൻ കണ്ടു. പള്ളിയിൽ എഴുന്നേറ്റു നിന്ന് അയാൾ ബാങ്ക് വിളിച്ചു. പിന്നെ ഇരുന്നു. എഴുന്നേറ്റുനിന്ന് വീണ്ടും അതാവർത്തിച്ചു. അതിലദ്ദേഹം ഖദ്ഖാമത്തി സ്വലാത്ത് (നിശ്ചയം നിസ്കാരം നിർവ്വഹിക്കാറായി) എന്നുകൂടി പറഞ്ഞു. ജനങ്ങൾ ഒന്നും പറയില്ലായിരുന്നെങ്കിൽ ഉണർച്ചയിലാണ് അത് കണ്ടതെന്ന് ഞാൻ പറയുമായിരുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹു താങ്കൾക്ക് നല്ലതാണ് കാണിച്ചുതന്നത്. താങ്കൾ ബിലാലിനോട് ബാങ്ക് വിളിക്കാൻ കൽപിക്കുക." അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അദ്ദേഹം കണ്ടതുപോലെ ഞാനും കണ്ടിട്ടുണ്ട്. പക്ഷേ, ഞാൻ പറയുന്നതിനു മുമ്പുതന്നെ വിവരം ഇവിടെ എത്തിയതിനാൽ ഞാൻ പറയാൻ മടിച്ചതാണ്. (റിപ്പോർട്ടർ തുടരുന്നു) ഞങ്ങളുടെ കൂട്ടുകാർ ഞങ്ങളോട് പറഞ്ഞു: ആരെങ്കിലുമൊരാൾ വരുമ്പോൾ അയാളുടെ നിസ്കാരത്തെപ്പറ്റി ചോദിച്ചാൽ അയാൾ മുമ്പ് നിസ്കരിച്ചത് എങ്ങനെയെന്ന് പറയാറുണ്ട്. അവർ നിന്നും ഇരുന്നും റുകൂഇലും നിസ്കാരത്തിൽ നബിയെ പിൻതുടരാറുണ്ടായിരുന്നു. (ദ)', 'ابْنِ أَبِي لَيْلَى', 'ഇബ്നുഅബീലൈല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 289, 289, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِلَالًا أَنْ يَشْفَعَ الْأَذَانَ وَأَنْ يُوتِرَ الْإِقَامَةَ (ن)', 'അനസ്(റ): നബി(സ) ബിലാലിനോട് ബാങ്കിനെ (ബാങ്കിലെ വചനങ്ങളെ) ഇരട്ടയാക്കാനും ഇഖാമത്ത് (ഇഖാമത്തിലെ വചനങ്ങൾ) ഒറ്റയാക്കാനും കൽപിച്ചു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 289, 289, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ الْأَذَانُ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَثْنَى مَثْنَى وَالْإِقَامَةُ مَرَّةً مَرَّةً إِلَّا أَنَّكَ تَقُولُ قَدْ قَامَتِ الصَّلَاةُ قَدْ قَامَتِ الصَّلَاةُ (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ)യുടെ കാലത്ത് ബാങ്കിന്റെ വചനങ്ങൾ ഈരണ്ടായും, ഇഖാമത്തിന്റെ വചനങ്ങൾ ഒറ്റയായും ആയിരുന്നു. പക്ഷേ, ''ഖദ്ഖാമത്തി സ്സ്വലാത്ത്'' എന്ന് രണ്ടു പ്രാവശ്യം പറയണം. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 289, 289, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُمِرَ بِلَالٌ أَنْ يَشْفَعَ الْأَذَانَ وَيُوتِرَ الْإِقَامَةَ – وفي رواية – إِلَّا الْإِقَامَةَ (ق,د,ت,ن,جه)', 'അനസുബ്നു മാലിക്(റ): ബാങ്കിന്റെ വചനങ്ങൾ ഇരട്ടയാക്കാനും ഇഖാമത്തിന്റെ വചനങ്ങൾ ഒറ്റയാക്കാനും ബിലാൽ കൽപിക്കപ്പെട്ടു. മറ്റൊരു റിപ്പോർട്ടിൽ: ഇഖാമത്ത് ഒഴികെ. (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 290, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=15 and h.hadith_no=13), 1, 'وَفِي رِوَايَةٍ – إِلَّا الْإِقَامَةَ (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: ഇഖാമത്ത് ഒഴികെ. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ عَبْدِ اللهِ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ أَذَانُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَفْعًا شَفْعًا فِي الْأَذَانِ وَالْإِقَامَةِ. (ت)', 'അബ്ദില്ലാഹിബ്നു സൈദ്(റ): നബി(സ)യുടെ ബാങ്കിന്റെയും ഇഖാമത്തിന്റെയും വചനങ്ങൾ ഈരണ്ടീരണ്ടായിരുന്നു. (തു)', 'عَبْدِ اللهِ بْنِ زَيْدٍ', 'അബ്ദില്ലാഹിബ്നു സൈദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 290, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ بِلَالٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُثَوِّبَنَّ فِي شَيْءٍ مِنَ الصَّلَوَاتِ إِلَّا فِي صَلَاةِ الْفَجْرِ". (ت)', 'ബിലാൽ(റ): നബി(സ) എന്നോട് പറഞ്ഞു: "സുബ്ഹ്നല്ലാതെ മറ്റൊരു ബാങ്കിലും തസ്വീബ്¹ സുന്നത്തില്ല." (തു)', 'بِلَالٍ', 'ബിലാൽ(റ)', '¹. അസ്സ്വലാതു ഖൈറുന്മിനന്നൗം എന്ന വാചകം', null, array['ت']::text[], array['തു']::text[], null, null, 290, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي مَحْذُورَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أُؤَذِّنُ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَكُنْتُ أَقُولُ فِي أَذَانِ الْفَجْرِ الْأَوَّلِ: حَيَّ عَلَى الْفَلَاحِ، الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ، الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ، اللهُ أَكْبَرُ، اللهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللهُ (ن)', 'അബൂമഹ്ദൂറ(റ): ഞാൻ നബി(സ)യുടെയടുത്ത് ബാങ്കു വിളിച്ചു. സുബ്ഹിയുടെ ആദ്യ ബാങ്കിൽ ഇപ്രകാരം പറഞ്ഞു: ''വിജയത്തിലേക്ക് വരിക, നിസ്കാരം ഉറക്കത്തേക്കാൾ ഉത്തമമാകുന്നു. (രണ്ടു തവണ). അല്ലാഹു ഏറ്റവും വലിയവനാകുന്നു (രണ്ട് തവണ) അല്ലാഹു അല്ലാതെ മറ്റൊരാരാധ്യനില്ല.'' (ന)', 'أَبِي مَحْذُورَةَ', 'അബൂമഹ്ദൂറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 290, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: وَقَدْ سُئِلَ عَنِ الْأَذَانِ فَقَالَ: كَانَ الْأَذَانُ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَثْنَى مَثْنَى، وَالْإِقَامَةُ مَرَّةً مَرَّةً إِلَّا أَنَّكَ إِذَا قُلْتَ قَدْ قَامَتِ الصَّلَاةُ، قَالَهَا مَرَّتَيْنِ فَإِذَا سَمِعْنَا قَدْ قَامَتِ الصَّلَاةُ تَوَضَّأْنَا ثُمَّ خَرَجْنَا إِلَى الصَّلَاةِ. (ن)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹത്തോട് ബാങ്കിനെക്കുറിച്ചു ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ)യുടെ കാലത്ത് ബാങ്കിലെ വചനങ്ങൾ ഈരണ്ടീരണ്ടായിരുന്നു. ഇഖാമത്ത് ഓരോന്നോരോന്നായിട്ടും. എന്നാൽ ''ഖദ്ഖാമത്തി സ്വലാത്ത്'' എന്നത് രണ്ടുപ്രാവശ്യം പറയാറുണ്ടായിരുന്നു. ഞങ്ങൾ ഖദ്ഖാമതിസ്സ്വലാത് എന്നുകേട്ടാൽ വുളു ചെയ്ത് നിസ്കാരത്തിനായി പുറപ്പെടും. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 290, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ سَعْدِ بْنِ عَائِذٍ رَضِيَ اللهُ عَنْهُ مُؤَذِّنِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ أَذَانَ بِلَالٍ كَانَ مَثْنَى مَثْنَى وَإِقَامَتَهُ مُفْرَدَةً. (جه)', 'നബി(സ)യുടെ മുഅദ്ദിനായ സഅദ്ബ്നു ആഇദ്(റ): ബിലാലിന്റെ ബാങ്കിന്റെ വചനങ്ങൾ ഈരണ്ടു വീതവും ഇഷാമതിന്റെ വചനങ്ങൾ ഒറ്റയായും ആയിരുന്നു. (ജ)', 'سَعْدِ بْنِ عَائِذٍ', 'നബി(സ)യുടെ മുഅദ്ദിനായ സഅദ്ബ്നു ആഇദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 290, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ مُجَاهِدٍ قَالَ: كُنْتُ مَعَ ابْنِ عُمَرَ فَثَوَّبَ رَجُلٌ فِي الظُّهْرِ أَوِ الْعَصْرِ، قَالَ: اخْرُجْ بِنَا، فَإِنَّ هَذِهِ بِدْعَةٌ. (د,ت)', 'മുജാഹിദ്(റ): ഞാൻ ഇബ്നുഉമറിന്റെ കൂടെയായിരിക്കെ ഒരാൾ ളുഹ്റിലോ -അല്ലെങ്കിൽ അസ്റിലോ- തസ്വീബ് ചൊല്ലി. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നീ ഞങ്ങളുടെ അടുത്ത് നിന്നു പോകൂ! ഇത് ബിദ്അത്താണ്. (ദ,തു)', 'مُجَاهِدٍ قَالَ', 'മുജാഹിദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 290, 291, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ أَبِي رَافِعٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ بِلَالًا يُؤَذِّنُ بَيْنَ يَدَيْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَثْنَى مَثْنَى وَيُقِيمُ وَاحِدَةً. (جه)', 'അബൂറാഫിഅ്(റ): റസൂലിന്റെ അടുത്തു വെച്ചു ബിലാൽ(റ) ബാങ്ക് ഈരണ്ടായും ഇഖാമത്ത് ഒറ്റയായും വിളിക്കുന്നത് ഞാൻ കേട്ടു. (ജ)', 'أَبِي رَافِعٍ', 'അബൂറാഫിഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 291, 291, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ – وَكَانَ فِي حِجْرِ أَبِي سَعِيدٍ – قَالَ: قَالَ لِي أَبُو سَعِيدٍ رَضِيَ اللهُ عَنْهُمَا: إِذَا كُنْتَ فِي الْبَوَادِي فَارْفَعْ صَوْتَكَ بِالْأَذَانِ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَسْمَعُهُ جِنٌّ وَلَا إِنْسٌ وَلَا شَجَرٌ وَلَا حَجَرٌ إِلَّا شَهِدَ لَهُ". (خ,جه)', 'അബ്ദുറഹ്മാനുബ്നു അബീസഅ്സഅ(റ): (അദ്ദേഹം അബൂസഈദി(റ)ന്റെ സംരക്ഷണയിലായിരുന്നു.) അബൂസഈദ് എന്നോട് പറഞ്ഞു: നീ താഴ്വരയിലാകുമ്പോൾ ഉച്ചത്തിൽ ബാങ്ക് വിളിക്കുക. നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: " ബാങ്ക് കേൾക്കുന്ന ജിന്നുകളും, മനുഷ്യരും, മരങ്ങളും, കല്ലുകളും, അയാൾക്കുവേണ്ടി(ബാങ്ക് വിളിക്കുന്നവനുവേണ്ടി) അവ സാക്ഷികളാതിരിക്കില്ല." (ബു,ജ)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ – وَكَانَ فِي حِجْرِ أَبِي سَعِيدٍ – قَالَ', 'അബ്ദുറഹ്മാനുബ്നു അബീസഅ്സഅ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 291, 291, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْمُؤَذِّنُ يُغْفَرُ لَهُ مَدَى صَوْتِهِ، وَيَسْتَغْفِرُ لَهُ كُلُّ رَطْبٍ وَيَابِسٍ، وَشَاهِدُ الصَّلَاةِ يُكْتَبُ لَهُ خَمْسٌ وَعِشْرُونَ حَسَنَةً، وَيُكَفَّرُ عَنْهُ مَا بَيْنَهُمَا". (د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "ബാങ്ക് വിളിക്കുന്നവന് അയാളുടെ ശബ്ദം എത്തുന്നിടത്തോളം പാപങ്ങൾ പൊറുക്കപ്പെടുന്നു. എല്ലാ ജീവനുള്ളവയും അല്ലാത്തവയും അവനു വേണ്ടി പാപമോചനത്തിനപേക്ഷിക്കുന്നു. നിസ്കാരത്തിനു വരുന്നവർക്ക് ഇരുപത്തിയഞ്ച് നന്മകൾ രേഖപ്പെടുത്തപ്പെടുന്നു. രണ്ട് ബാങ്കുകൾക്കിടയിൽ വന്നുപോകുന്ന തെറ്റുകൾ അവന് മായ്ക്കപ്പെടുന്നു." (ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 291, 291, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَذَّنَ سَبْعَ سِنِينَ مُحْتَسِبًا كُتِبَتْ لَهُ بَرَاءَةٌ مِنَ النَّارِ". (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിൽ നിന്നു മാത്രം പ്രതിഫലം കാംക്ഷിച്ചു കൊണ്ട് ഏഴുവർഷം ആരെങ്കിലും ബാങ്ക് വിളിച്ചാൽ അയാൾക്ക് നരക വിമുക്തി ഉറപ്പായി." (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 291, 291, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا نُودِيَ لِلصَّلَاةِ أَدْبَرَ الشَّيْطَانُ وَلَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ التَّأْذِينَ، فَإِذَا قُضِيَ النِّدَاءُ أَقْبَلَ، حَتَّى إِذَا ثُوِّبَ بِالصَّلَاةِ أَدْبَرَ، حَتَّى إِذَا قُضِيَ التَّثْوِيبُ أَقْبَلَ، حَتَّى يَخْطُرَ بَيْنَ الْمَرْءِ وَنَفْسِهِ يَقُولُ: اذْكُرْ كَذَا، اذْكُرْ كَذَا لِمَا لَمْ يَكُنْ يَذْكُرُ، حَتَّى يَظَلَّ الْمَرْءُ إِنْ يَدْرِي كَمْ صَلَّى". (ق,د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിസ്കാരത്തിന്നായി ബാങ്ക് വിളിക്കുമ്പോൾ ബാങ്ക് കേൾക്കാത്തിടം വരെ കീഴ്വായു പുറപ്പെടുവിച്ചു കൊണ്ട് പിശാച് പിന്തിരിഞ്ഞോടുന്നു. ബാങ്ക് കഴിഞ്ഞാൽ തിരിച്ചുവരുന്നു. ഇഖാമത്ത് വിളിക്കുമ്പോൾ വീണ്ടും പിന്തിരിഞ്ഞോടുന്നു. ഇഖാമത്ത് വിളിച്ചു കഴിഞ്ഞാൽ തിരിച്ചു വരികയും മനുഷ്യ മനസ്സിൽ പ്രശ്നങ്ങൾ സൃഷ്ടിച്ചു കൊണ്ടിരിക്കുകയും ചെയ്യുന്നു. ഓർക്കരുതാത്തതെല്ലാം ഓർക്കാൻ പറയുന്നു. എത്ര നിസ്കരിച്ചു എന്നു പോലും അറിയാൻ കഴിയാത്ത വിധത്തിലാക്കുന്നു." (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 291, 292, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمُؤَذِّنُونَ أَطْوَلُ النَّاسِ أَعْنَاقًا يَوْمَ الْقِيَامَةِ". (م,جه)', 'മുആവിയതുബ്നു അബീസുഫ്യാൻ(റ): നബി(സ) പറഞ്ഞു: "ബാങ്ക് വിളിക്കുന്നവർ അന്ത്യനാളിൽ ജനങ്ങളിൽ ഏറ്റവും തലയെടുപ്പുള്ളവരായിരിക്കും." (മു,ജ)', 'مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ', 'മുആവിയതുബ്നു അബീസുഫ്യാൻ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 292, 292, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لِيُؤَذِّنْ لَكُمْ خِيَارُكُمْ وَلْيَؤُمَّكُمْ قُرَّاؤُكُمْ". (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽഏറ്റവും ഉത്തമർ ബാങ്ക് വിളിക്കുകയും, നന്നായി ഖുർആൻ പാരായണം ചെയ്യുന്നവർ ഇമാമാകുകയും ചെയ്യട്ടെ." (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 292, 292, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَذَّنَ ثِنْتَيْ عَشْرَةَ سَنَةً وَجَبَتْ لَهُ الْجَنَّةُ,وَكُتِبَ لَهُ بِتَأْذِينِهِ فِي كُلِّ يَوْمٍ سِتُّونَ حَسَنَةً، وَلِكُلِّ إِقَامَةٍ ثَلَاثُونَ حَسَنَةً". (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ പന്ത്രണ്ട് വർഷം ബാങ്ക് വിളിച്ചാൽ അയാൾക്ക് സ്വർഗ്ഗം നിർബന്ധമായി. ഓരോ ദിവസവും അയാൾ വിളിക്കുന്ന ബാങ്ക് മുഖേന അയാൾക്ക് അറുപത് നന്മ രേഖപ്പെടുത്തപ്പെടും. ഓരോ ഇഖാമത്തിനും മുപ്പത് നന്മയും." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 292, 292, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْإِمَامُ ضَامِنٌ وَالْمُؤَذِّنُ مُؤْتَمَنٌ، اللَّهُمَّ أَرْشِدِ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِينَ". (د,ت)', 'അഹബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഇമാം (നിസ്കാരത്തിന് നേതൃത്വം നൽകുന്നയാൾ) ഉത്തരവാദപ്പെട്ടവനാണ്, മുഅദ്ദിൻ (ബാങ്ക് വിളിക്കുന്നയാൾ) വിശ്വസിക്കപ്പെടേണ്ടവനുമാണ്. അല്ലാഹുവേ, ഇമാമുകൾക്ക് നീ മാർഗ്ഗ ദർശനം നൽകേണമേ, മുഅദ്ദിനുകൾക്ക് പൊറുത്തു കൊടുക്കേണമേ." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അഹബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 292, 292, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْ يَعْلَمُ النَّاسُ مَا فِي النِّدَاءِ وَالصَّفِّ الْأَوَّلِ ثُمَّ لَمْ يَجِدُوا إِلَّا أَنْ يَسْتَهِمُوا عَلَيْهِ لَاسْتَهَمُوا عَلَيْهِ، وَلَوْ يَعْلَمُونَ مَا فِي التَّهْجِيرِ لَاسْتَبَقُوا إِلَيْهِ، وَلَوْ عَلِمُوا مَا فِي الْعَتَمَةِ وَالصُّبْحِ لَأَتَوْهُمَا وَلَوْ حَبْوًا". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ബാങ്കിന്റെയും ഒന്നാമത്തെ അണിയുടെയും പ്രതിഫലം ജനം അറിഞ്ഞിരുന്നുവെങ്കിൽ അതിന്നു നറുക്കെടുക്കേണ്ടി വന്നാൽ അവരങ്ങനെ ചെയ്യുമായിരുന്നു. ഉച്ചസമയത്തെ നിസ്കാരത്തെക്കുറിച്ച് അറിഞ്ഞിരുന്നുവെങ്കിൽ അതിനായി മത്സരിക്കുമായിരുന്നു. ഇശാഇന്റെയും സുബ്ഹിന്റെയും പ്രാധാന്യം അറിഞ്ഞിരുന്നുവെങ്കിൽ ഇഴഞ്ഞുകൊണ്ടെങ്കിലും അവർ എത്തുമായിരുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 292, 292, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُغِيرُ إِذَا طَلَعَ الْفَجْرُ، وَكَانَ يَسْتَمِعُ الْأَذَانَ، فَإِنْ سَمِعَ أَذَانًا أَمْسَكَ، وَإِلَّا أَغَارَ، فَسَمِعَ رَجُلًا يَقُولُ: اللهُ أَكْبَرُ اللهُ أَكْبَرُ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَى الْفِطْرَةِ" ثُمَّ قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَرَجْتَ مِنَ النَّارِ" فَنَظَرُوا فَإِذَا هُوَ رَاعِي مَعْزًى. (م)', 'അനസ്ബ്നു മാലിക്(റ): നബി(സ) പ്രഭാതത്തിൽ യുദ്ധം ചെയ്യും. ബാങ്കു കേൾക്കുന്നുണ്ടോ എന്നു ശ്രദ്ധിക്കുന്നുണ്ടാവും. ബാങ്ക് കേട്ടാൽ ആക്രമണം അവസാനിപ്പിക്കും. അല്ലെങ്കിൽ തുടരും. അങ്ങനെ ഒരാൾ അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ എന്നുപറയുന്നതു കേട്ടു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു. "പ്രകൃത്യാ അങ്ങനെ തന്നെ." പിന്നീട് അയാൾ ''അശ്ഹദു അൻലാഇലാഹ ഇല്ലല്ലാഹു, അശ്ഹദു അൻലാഇലാഹ ഇല്ലല്ലാഹു'' എന്ന് പറഞ്ഞു. ഉടനെ നബി(സ) പറഞ്ഞു. "താങ്കൾ നരകത്തിൽ നിന്ന് രക്ഷപ്പെട്ടു." അവർ നോക്കിയപ്പോൾ അയാൾ ഒരിടയനായിരുന്നു. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്ബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 292, 293, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: سَمِعَهُ مِنْ فَمِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْمُؤَذِّنُ يُغْفَرُ لَهُ بِمَدِّ صَوْتِهِ وَيَشْهَدُ لَهُ كُلُّ رَطْبٍ وَيَابِسٍ". (ن)', 'അബൂഹുറൈറ(റ): (റസൂൽ(സ) ഇപ്രകാരം പറയുന്നതായി) അദ്ദേഹം റസൂലിൽ നിന്നും നേരിട്ടു കേട്ടു: "ബാങ്ക് വിളിക്കുന്നവന് അയാളുടെ ശബ്ദത്തോളം പൊറുത്തു കൊടുക്കുന്നതാണ്. എല്ലാ ജീവനുള്ളവയും നിർജ്ജീവമായതും അയാൾക്കു വേണ്ടി സാക്ഷ്യം വഹിക്കുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 293, 293, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الصَّفِّ الْمُقَدَّمِ، وَالْمُؤَذِّنُ يُغْفَرُ لَهُ بِمَدِّ صَوْتِهِ، وَيُصَدِّقُهُ مَنْ سَمِعَهُ مِنْ رَطْبٍ وَيَابِسٍ، وَلَهُ مِثْلُ أَجْرِ مَنْ صَلَّى مَعَهُ". (ن)', 'ബർറാഉബ്നു ആസിബ്(റ): നബി(സ) പറഞ്ഞു: "(നിസ്കാരത്തിലെ) മുന്നിലെ അണി(യിലുള്ളവർ)ക്കുവേണ്ടി അല്ലാഹുവും അവന്റെ മലക്കുകളും സ്വലാത്ത് ചൊല്ലന്നു. ബാങ്ക് വിളിക്കുന്നവന്ന് അവന്റെ ശബ്ദം എത്തുന്നേടത്തോളം പൊറുത്തു കൊടുക്കുന്നു. അതു കേൾക്കുന്ന ഉണങ്ങിയതും പച്ചയുമെല്ലാം അത് സത്യമാക്കുന്നു. അയാൾക്ക് അയാളോടൊപ്പം നിസ്കരിച്ചവർക്ക് കിട്ടുന്ന പ്രതിഫലത്തിന് തുല്യമായത് ലഭിക്കുകയും ചെയ്യുന്നു." (ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബർറാഉബ്നു ആസിബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 293, 293, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ سَعْدِ بْنِ عَائِذٍ رَضِيَ اللهُ عَنْهُ مُؤَذِّنِ الرَّسُولِ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِلَالًا أَنْ يَجْعَلَ إِصْبَعَيْهِ فِي أُذُنَيْهِ وَقَالَ: "إِنَّهُ أَرْفَعُ لِصَوْتِكَ". (جه)', 'നബിയുടെ മുഅദ്ദിനായ സഅദ്ബ്നുആഇദ്(റ): നബി(സ) ബിലാലിനോട് ചൂണ്ടുവിരലുകൾ ചെവികളിൽ വെക്കാൻ കൽപിച്ചു കൊണ്ട് പറഞ്ഞു: "ശബ്ദമുയർത്താൻ അത് സഹായകമാണ്." (ജ)', 'سَعْدِ بْنِ عَائِذٍ', 'നബിയുടെ മുഅദ്ദിനായ സഅദ്ബ്നുആഇദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 293, 293, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْأَبْطَحِ وَهُوَ فِي قُبَّةٍ حَمْرَاءَ فَخَرَجَ بِلَالٌ فَأَذَّنَ فَاسْتَدَارَ فِي أَذَانِهِ وَجَعَلَ إِصْبَعَيْهِ فِي أُذُنَيْهِ (ق,جه)', 'അബൂജുഹൈഫ(റ): ഞാൻ റസൂലി(സ)ന്റെ അടുത്ത് ''അബ്ത്വഹ്'' എന്ന സ്ഥലത്ത് ചെന്നു. അദ്ദേഹം ചുവന്ന കൂടാരത്തിലായിരുന്നു. അപ്പോൾ ബിലാൽ വന്നു ബാങ്ക് വിളിച്ചു. ബാങ്ക് വിളിക്കുമ്പോൾ (ഇരുഭാഗത്തേക്കും) തിരിയുന്നുണ്ടായിരുന്നു. രണ്ടു വിരലുകൾ രണ്ടു ചെവികളിലും തിരുകിയിരുന്നു. (ബു,മു,ജ)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 293, 293, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ بِلَالًا يُؤَذِّنُ وَيَدُورُ، وَيُتْبِعُ فَاهُ هَهُنَاوَهَهُنَا، وَإِصْبَعَاهُ فِي أُذُنَيْهِ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي قُبَّةٍ لَهُ حَمْرَاءَ أُرَاهُ مِنْ أَدَمٍ، فَخَرَجَ بِلَالٌ بَيْنَ يَدَيْهِ بِالْعَنَزَةِ، فَرَكَزَهَا بِالْبَطْحَاءِ، فَصَلَّى إِلَيْهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، يَمُرُّ بَيْنَ يَدَيْهِ الْكَلْبُ وَالْحِمَارُ، وَعَلَيْهِ حُلَّةٌ حَمْرَاءُ كَأَنِّي أَنْظُرُ إِلَى بَرِيقِ سَاقَيْهِ. (ق,ت)', 'അബൂജുഹൈഫ(റ): ബിലാൽ(റ) ബാങ്ക് വിളിക്കുമ്പോൾ അങ്ങോട്ടുമിങ്ങോട്ടും തിരിയുന്നതും വായ അങ്ങോട്ടുമിങ്ങോട്ടും തിരിക്കുന്നതും ഞാൻ കണ്ടു. രണ്ടു വിരലുകൾ രണ്ടു ചെവികളിൽ വെച്ചിരുന്നു. നബി(സ) തോലുകൊണ്ടുള്ള തന്റെ ചുവന്ന കൂടാരത്തിലായിരുന്നു. ബിലാൽ നബിയുടെ അടുത്ത് ഒരു വടിയുമായി വന്ന് അതു മണലിൽ കുത്തിവെച്ചു. നബി(സ) അതിലേക്കു തിരിഞ്ഞു നിസ്കരിച്ചു. മുന്നിലൂടെ കഴുതയും നായയും നടന്നിരുന്നു. നബി(സ) ചുവന്ന വസ്ത്രം ധരിച്ചിരുന്നു. അവിടുത്തെ കാലിന്റെ വെണ്മ ഞാൻ (ഇപ്പോഴും) നോക്കിക്കാണുന്നത് പോലെയുണ്ട്. (ബു,മു,തു)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 293, 294, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "إِنِّي أَرَاكَ تُحِبُّ الْغَنَمَ وَالْبَادِيَةَ، فَإِذَا كُنْتَ فِي غَنَمِكَ أَوْ بَادِيَتِكَ فَأَذَّنْتَ بِالصَّلَاةِ فَارْفَعْ صَوْتَكَ، فَإِنَّهُ لَا يَسْمَعُ مَدَى صَوْتِ الْمُؤَذِّنِ جِنٌّ وَلَا إِنْسٌ وَلَا شَيْءٌ إِلَّا شَهِدَ لَهُ يَوْمَ الْقِيَامَةِ". (خ,ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "താങ്കൾ ആടുകളേയും മേച്ചിൽ പുറങ്ങളേയും ഇഷ്ടപ്പെടുന്നയാളായി ഞാൻ മനസ്സിലാക്കുന്നു. ആടുകളുടെ കൂടെയോ താഴ്വരയിലോ ആയിരിക്കെ ബാങ്കിന്റെ ശബ്ദമുയർത്തുക. ബാങ്കു വിളിക്കുന്നയാളുടെ ശബ്ദം കേൾക്കുന്ന ജിന്നുകളും മനുഷ്യരും മറ്റെല്ലാം അന്ത്യനാളിൽ അയാൾക്കുവേണ്ടി സാക്ഷ്യം വഹിക്കുക തന്നെ ചെയ്യും." (ബു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 294, 294, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَصْلَتَانِ مُعَلَّقَتَانِ فِي أَعْنَاقِ الْمُؤَذِّنِينَ لِلْمُسْلِمِينَ، صَلَاتُهُمْ وَصِيَامُهُمْ". (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "മുസ്ലിംകളുടെ രണ്ടു കാര്യങ്ങൾ ബാങ്ക് വിളിക്കുന്നവരുടെ പിരടിയിൽ ബന്ധിക്കപ്പെട്ടിരിക്കുന്നു. അവരുടെ നിസ്കാരവും നോമ്പുമാണത്." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 294, 294, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ بِلَالٌ لَا يُؤَخِّرُ الْأَذَانَ عَنِ الْوَقْتِ، وَرُبَّمَا أَخَّرَ الْإِقَامَةَ شَيْئًا. (جه)', 'ജാബിറുബ്നു സമുറ(റ): ബിലാൽ(റ) ബാങ്കിനെ നിശ്ചിത സമയത്തിൽ നിന്നും പിന്തിക്കാറുണ്ടായിരുന്നില്ല. ചിലപ്പോൾ ഇഖാമത്ത് അല്പം പിന്തിക്കുമായിരുന്നു. (ജ)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 294, 294, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ بِلَالٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أُثَوِّبَ فِي الْفَجْرِ وَنَهَانِي أَنْ أُثَوِّبَ فِي الْعِشَاءِ. (جه)', 'ബിലാൽ(റ): സുബ്ഹി ബാങ്കിൽ ''അസ്സ്വലാത്തു ഖൈറുൻ മിനന്നൗം'' എന്നുപറയാൻ നബി(സ) എന്നോട് കൽപിച്ചു. എന്നാൽ, ഇശാഇന് അതു പറയുന്നത് വിലക്കുകയും ചെയ്തു. (ജ)', 'بِلَالٍ', 'ബിലാൽ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 294, 294, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ بِلَالٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُؤْذِنُهُ بِصَلَاةِ الْفَجْرِ فَقِيلَ: هُوَ نَائِمٌ، فَقَالَ: الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ، الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ، فَأُقِرَّتْ فِي تَأْذِينِ الْفَجْرِ، فَثَبَتَ الْأَمْرُ عَلَى ذَلِكَ. (جه)', 'ബിലാൽ(റ): അദ്ദേഹം സുബ്ഹി നിസ്കാരത്തിനു ബാങ്ക് വിളിക്കാനായി നബി(സ)യുടെ അടുത്തെത്തി. നബി(സ) ഉറക്കത്തിലാണെന്ന് അദ്ദേഹത്തോട് പറയപ്പെട്ടു. അപ്പോൾ: "നിസ്കാരം ഉറക്കിനേക്കാൾ ഉത്തമം, നിസ്കാരം ഉറക്കിനേക്കാൾ ഉത്തമം" എന്നു പറഞ്ഞു. അങ്ങിനെ അത് സുബ്ഹി ബാങ്കിൽ സ്ഥിരപ്പെടുത്തി. അങ്ങനെയാണ് ഈ വാചകം നിലവിൽ വന്നത്. (ജ)', 'بِلَالٍ', 'ബിലാൽ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 294, 294, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِبِلَالٍ: "يَا بِلَالُ! إِذَا أَذَّنْتَ فَتَرَسَّلْ فِي أَذَانِكَ، وَإِذَا أَقَمْتَ فَاحْدُرْ، وَاجْعَلْ بَيْنَ أَذَانِكَ وَإِقَامَتِكَ قَدْرَ مَا يَفْرُغُ الْآكِلُ مِنْ أَكْلِهِ وَالشَّارِبُ مِنْ شُرْبِهِ وَالْمُعْتَصِرُ إِذَا دَخَلَ لِقَضَاءِ حَاجَتِهِ وَلَا تَقُومُوا حَتَّى تَرَوْنِي". (ت)', 'ജാബിറുബ്നുഅബ്ദില്ല(റ): നബി(സ) ബിലാലിനോട് പറഞ്ഞു: "ബിലാൽ, നീ ധൃതിപ്പെടാതെ ബാങ്കു വിളിക്കുക. ഇഖാമത്ത് വേഗത്തിൽ നിർവ്വഹിക്കുക. നിന്റെ ബാങ്കിന്റെയും ഇഖാമത്തിന്റെയും ഇടയിൽ, ഭക്ഷണം കഴിക്കുന്നവന് അത് കഴിയും വരെയും കുടിക്കുന്നവന് അത് കഴിയുംവരെയും പ്രാഥമിക കൃത്യം നിർവ്വഹിക്കുന്നവന് അത് കഴിയുന്നതു വരെയുമുള്ള സമയം നൽകുക. എന്നെ കാണുംവരെ നിങ്ങൾ (നിസ്കാരത്തിനായി) നിൽക്കരുത്." (തു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നുഅബ്ദില്ല(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 294, 294, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمَكَّةَ وَهُوَ فِي قُبَّةٍ حَمْرَاءَ مِنْ أَدَمٍ، فَخَرَجَ بِلَالٌ فَأَذَّنَ فَكُنْتُ أَتَتَبَّعُ فَمَهُ هَهُنَا وَهَهُنَا، قَالَ: ثُمَّ خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ حُلَّةٌ حَمْرَاءُ بُرُودٌ يَمَانِيَةٌ قِطْرِيٌّ قَالَ: رَأَيْتُ بِلَالًا خَرَجَ إِلَى الْأَبْطَحِ فَأَذَّنَ، فَلَمَّا بَلَغَ حَيَّ عَلَى الصَّلَاةِ حَيَّ عَلَى الْفَلَاحِ لَوَى عُنُقَهُ يَمِينًا وَشِمَالًا وَلَمْ يَسْتَدِرْ، ثُمَّ دَخَلَ فَأَخْرَجَ الْعَنَزَةَ..... وَسَاقَ الْحَدِيثَ (ق,د,ن,جه)', 'അബൂജുഹൈഫ(റ): ഞാൻ റസൂലിന്റെ അടുത്ത് മക്കയിൽ ചെന്നു. നബി തോൽ കൊണ്ടുള്ള ചുവന്ന കൂടാരത്തിലായിരുന്നു. ബിലാൽ വന്നു ബാങ്ക് വിളിച്ചു. അദ്ദേഹത്തിന്റെ വായ അങ്ങോട്ടുമിങ്ങോട്ടും ചലിക്കുന്നത് ഞാൻ ശ്രദ്ധിച്ചു. പിന്നെ നബി(സ) ചുവന്ന യമനി പുതപ്പ് ധരിച്ചുകൊണ്ട് പുറത്തുവന്നു. അബൂജുഹൈഫ(റ) പറഞ്ഞു. ബിലാൽ അബ്ത്വഹിൽ പോയി ബാങ്കു വിളിക്കുന്നത് ഞാൻ കണ്ടു. ഹയ്യ അലസ്വലാത്ത്, ഹയ്യ അലൽഫലാഹ് എന്നു പറയുമ്പോൾ പിരടി വലത്തോട്ടും ഇടത്തോട്ടും തിരിച്ചു. എന്നാൽ ചുറ്റും തിരിഞ്ഞിരുന്നില്ല. പിന്നീട് കൂടാരത്തിൽ പ്രവേശിച്ച് വടി പുറത്തെടുത്തു... ഹദീസ് തുടർന്നു പറഞ്ഞു. (ബു,മു,ദ,ന,ജ)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 295, 295, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُ عَنِ امْرَأَةٍ مِنْ بَنِي النَّجَّارِ قَالَتْ: كَانَ بَيْتِي مِنْ أَطْوَلِ بَيْتٍ حَوْلَ الْمَسْجِدِ، وَكَانَ بِلَالٌ يُؤَذِّنُ عَلَيْهِ الْفَجْرَ، فَيَأْتِي بِسَحَرٍ فَيَجْلِسُ عَلَى الْبَيْتِ يَنْظُرُ إِلَى الْفَجْرِ، فَإِذَا رَآهُ تَمَطَّى، ثُمَّ قَالَ: اللَّهُمَّ إِنِّي أَحْمَدُكَ وَأَسْتَعِينُكَ عَلَى قُرَيْشٍ أَنْ يُقِيمُوا دِينَكَ، قَالَتْ: ثُمَّ يُؤَذِّنُ، قَالَتْ: وَاللَّهِ مَا عَلِمْتُهُ كَانَ تَرَكَهَا لَيْلَةً وَاحِدَةً تَعْنِي هَذِهِ الْكَلِمَاتِ (د)', 'ഉർവത്തുബ്നു സുബൈർ(റ): ബനു നജ്ജാറിലെ ഒരു സ്ത്രീ പറഞ്ഞു: എന്റെ വീട് പള്ളിയുടെ അടുത്തുള്ള ഏറ്റവും ഉയരം കൂടിയ വീടായിരുന്നു. ബിലാൽ ഫജ്ർ ബാങ്ക് വിളിച്ചത് അവിടെ നിന്നാണ്. പ്രഭാതത്തിനു മുമ്പ് അവിടെ എത്തി പ്രഭാതം പ്രതീക്ഷിച്ചിരിക്കും. പ്രഭാതം കണ്ടാൽ നീണ്ടുനിവർന്നിരുന്നു പറയും: അല്ലാഹുവേ, ഞാൻ നിന്നെ സ്തുതിക്കുന്നു. ഖുറൈശികൾ നിന്റെ മതത്തെ നിലനിർത്തുന്നവരായിത്തീരാൻ വേണ്ടി നിന്നോട് ഞാൻ സഹായം തേടുന്നു. പിന്നെ അദ്ദേഹം ബാങ്ക് വിളിക്കും. അവർ പറഞ്ഞു: ഈ വാക്കുകൾ ബിലാൽ ഒരിക്കലും ഉപേക്ഷിച്ചിരുന്നില്ല. (ദ)', 'عُرْوَةَ بْنِ الزُّبَيْرِ', 'ഉർവത്തുബ്നു സുബൈർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 295, 295, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يُؤَذِّنُ إِلَّا مُتَوَضِّئٌ" وعنه أيضا: "لَا يُنَادِي بِالصَّلَاةِ إِلَّا مُتَوَضِّئٌ". (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വുദു ഉള്ളവനല്ലാതെ ബാങ്ക് വിളിക്കരുത്." മറ്റൊരു റിപ്പോർട്ടിൽ: "വുദു ഉള്ളവനല്ലാതെ നിസ്കാരത്തിനു വേണ്ടി ബാങ്ക് വിളിക്കരുത്." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 295, 295, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=15 and h.hadith_no=44), 1, null, 'മറ്റൊരു നിവേദനിൽ: "വുദു ഉള്ളവനല്ലാതെ നിസ്കാരത്തിനു വേണ്ടി ബാങ്ക് വിളിക്കരുത്." (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا سَمِعْتُمُ النِّدَاءَ فَقُولُوا مِثْلَ مَا يَقُولُ الْمُؤَذِّنُ". (ق,د,ت,ن,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ബാങ്കുവിളി കേട്ടാൽ ബാങ്ക് വിളിക്കുന്നവൻ പറയുന്നതുപോലെ പറയുക." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 295, 295, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ: عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ حِينَ يَسْمَعُ الْمُؤَذِّنَ وَأَنَا أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ رَضِيتُ بِاللهِ رَبًّا وَبِمُحَمَّدٍ رَسُولًا وَبِالْإِسْلَامِ دِينًا غُفِرَ لَهُ ذَنْبُهُ". (م,د,ت,ن,جه)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): നബി(സ) പറഞ്ഞു: "ബാങ്ക് കേൾക്കുമ്പോൾ ''അല്ലാഹുവല്ലാതെ മറ്റൊരാരാധ്യനില്ലെന്നും അവൻ ഏകനാണെന്നും അവന് പങ്കുകാരില്ലെന്നും മുഹമ്മദ്(സ) അവന്റെ അടിമയും ദൂതനുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നുവെന്നും, അല്ലാഹുവിനെ ഞാൻ റബ്ബായും മുഹമ്മദിനെ ദൂതനായും ഇസ്ലാമിനെ മതമായും തൃപ്തിപ്പെട്ടു'' എന്നും ആരെങ്കിലും പറഞ്ഞാൽ അവന്റെ പാപങ്ങൾ പൊറുക്കപ്പെടുന്നതാണ്." (മു,ദ,തു,ന,ജ)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 295, 296, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ: اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ إِلَّا حَلَّتْ لَهُ الشَّفَاعَةُ يَوْمَ الْقِيَامَةِ". (خ,د,ت,ن,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറഞ്ഞു: "ഈ പരിപൂർണ്ണ വിളിയുടെയും നിലനിൽക്കുന്ന നിസ്കാരത്തിന്റെയും നാഥനായ അല്ലാഹുവേ, മുഹമ്മദ് നബിക്ക് നീ ''വസീലത്'', ''ഫദീലത്'' എന്നീ പദവികൾ നൽകുകയും അദ്ദേഹത്തിന് നീ വാഗ്ദാനം ചെയ്ത സ്തുത്യർഹമായ സ്ഥാനത്തേക്ക് അദ്ദേഹത്തെ ആനയിക്കുകയും ചെയ്യേണമേ; എന്ന് ബാങ്ക് കേൾക്കുമ്പോൾ ആര് പ്രാർത്ഥിച്ചുവോ അവർക്ക് അന്ത്യനാളിൽ ശുപാർശ ലഭിക്കാതിരിക്കില്ല." (ബു,ദ,തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 296, 296, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ بِلَالٌ يُنَادِي، فَلَمَّا سَكَتَ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَالَ مِثْلَ هَذَا يَقِينًا دَخَلَ الْجَنَّةَ". (ن)', 'അബൂഹുറൈറ(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പമായിരിക്കെ ബിലാൽ(റ) എഴുന്നേറ്റു ബാങ്കു വിളിച്ചു. അദ്ദേഹം നിർത്തിയപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇപ്രകാരം ദൃഢവിശ്വാസത്തോടു കൂടി ആർ പറയുന്നുവോ, അവൻ സ്വർഗ്ഗസ്ഥനാണ്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 296, 296, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا سَمِعْتُمُ الْمُؤَذِّنَ فَقُولُوا مِثْلَ مَا يَقُولُ، وَصَلُّوا عَلَيَّ، فَإِنَّهُ مَنْ صَلَّى عَلَيَّ صَلَاةً صَلَّى اللهُ عَلَيْهِ عَشْرًا، ثُمَّ سَلُوا اللهَ لِيَ الْوَسِيلَةَ، فَإِنَّهَا مَنْزِلَةٌ فِي الْجَنَّةِ لَا تَنْبَغِي إِلَّا لِعَبْدٍ مِنْ عِبَادِ اللهِ، أَرْجُو أَنْ أَكُونَ أَنَا هُوَ، فَمَنْ سَأَلَ لِيَ الْوَسِيلَةَ حَلَّتْ لَهُ الشَّفَاعَةُ". (م,د,ت,ن)', 'അബ്ദില്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിങ്ങൾ ബാങ്ക് കേട്ടാൽ മുഅദ്ദിൻ പറയുംപ്രകാരം പറയുകയും, എന്റെ പേരിൽ സ്വലാത്ത് ചൊല്ലുകയും ചെയ്യുക. ആർ എന്റെ പേരിൽ ഒരു സ്വലാത്ത് ചൊല്ലുന്നുവോ, അല്ലാഹു അവന്റെമേൽ പത്ത് സ്വലാത്ത് ചൊല്ലും. പിന്നെ നിങ്ങൾ അല്ലാഹുവിനോട് എനിക്കുവേണ്ടി വസീലത്തിനെ തേടുക. അല്ലാഹുവിന്റെ അടിമകളിൽ ഒരാൾക്കുമാത്രം നൽകുന്ന സ്വർഗ്ഗത്തിലെ അത്യുന്നത പദവിയാണത്. അത് ഞാനായിരിക്കുമെന്ന് എനിക്ക് പ്രതീക്ഷയുണ്ട്. ആർ എനിക്ക് വേണ്ടി വസീലത്തിനെ തേടിയോ, അയാൾക്ക് ശുപാർശ ലഭിക്കുന്നതാണ്." (മു,ദ,തു,ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദില്ലാഹിബ്നു അംറ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 296, 296, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا قَالَ الْمُؤَذِّنُ: اللهُ أَكْبَرُ اللهُ أَكْبَرُ، فَقَالَ أَحَدُكُمْ: اللهُ أَكْبَرُ اللهُ أَكْبَرُ، ثُمَّ قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، ثُمَّ قَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، قَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، ثُمَّ قَالَ: حَيَّ عَلَى الصَّلَاةِ، قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ، ثُمَّ قَالَ: حَيَّ عَلَى الْفَلَاحِ، قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ، ثُمَّ قَالَ: اللهُ أَكْبَرُ اللهُ أَكْبَرُ، قَالَ: اللهُ أَكْبَرُ اللهُ أَكْبَرُ، ثُمَّ قَالَ: لَا إِلَهَ إِلَّا اللهُ، قَالَ: لَا إِلَهَ إِلَّا اللهُ مِنْ قَلْبِهِ دَخَلَ الْجَنَّةَ". (م,د)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): നബി(സ) പറഞ്ഞു: "മുഅദ്ദിൻ, ''അല്ലാഹു അക്ബർ അല്ലാഹു അക്ബർ'' എന്നുപറയുമ്പോൾ നിങ്ങളിലാരെങ്കിലും ''അല്ലാഹു അക്ബർ അല്ലാഹു അക്ബർ'' എന്നു പറയുകയും, പിന്നെ ''അശ്ഹദു അൻലാഇലാഹ ഇല്ലല്ലാഹ്'' എന്നു പറയുമ്പോൾ അപ്രകാരവും, ''അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാഹ്'' എന്നു പറയുമ്പോൾ അപ്രകാരവും, ''ഹയ്യ അലസ്സലാഃ'' എന്നു പറയുമ്പോൾ ''ലാ ഹൗല വലാഖുവ്വത ഇല്ലാ ബില്ലാഹ്'' (ശക്തിയും കഴിവും അല്ലാഹു മുഖേനയല്ലാതെ ഇല്ല) എന്നും, ''ഹയ്യ അലൽ ഫലാഹ്'' എന്നു പറയുമ്പോൾ ''ലാ ഹൗല വലാഖുവ്വത ഇല്ലാബില്ലാഹ്'' എന്നും, ''അല്ലാഹു അക്ബർ അല്ലാഹു'' അക്ബർ എന്നു പറയുമ്പോൾ അപ്രകാരവും, ''ലാഇലാഹ ഇല്ലല്ലാഹ്'' എന്നു പറയുമ്പോൾ അപ്രകാരവും മനസ്സിൽ ഉറപ്പിച്ച് പറഞ്ഞാൽ അയാൾ സ്വർഗ്ഗസ്ഥനാണ്." (മു,ദ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 296, 297, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللهِ! إِنَّ الْمُؤَذِّنِينَ يَفْضُلُونَنَا؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "قُلْ كَمَا يَقُولُونَ، فَإِذَا انْتَهَيْتَ فَسَلْ تُعْطَهْ". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഒരാൾ ചോദിച്ചു: നബിയേ, ബാങ്ക് വിളിക്കുന്നവർ ഞങ്ങളേക്കാൾ ശ്രേഷ്ഠരാവുകയില്ലേ? നബി(സ) പറഞ്ഞു: "അവർ പറയുന്നതു പോലെ നീയും പറയുക. നീ പറഞ്ഞു തീർന്നാൽ വേണ്ടത് നീ ചോദിക്കുക. നിനക്ക് നൽകപ്പെടും." (ദ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 297, 297, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا سَمِعَ الْمُؤَذِّنَ يَتَشَهَّدُ قَالَ: "وَأَنَا وَأَنَا". (د)', 'ആഇശ(റ): മുഅദ്ദിൻ ''അശ്ഹദു.........'' പറയുന്നത് കേട്ടാൽ നബി(സ) ''ഞാനും, ഞാനും'' എന്നു പറയാറുണ്ടായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 297, 297, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: عَلَّمَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أَقُولَ عِنْدَ أَذَانِ الْمَغْرِبِ "اللَّهُمَّ إِنَّ هَذَا إِقْبَالُ لَيْلِكَ وَإِدْبَارُ نَهَارِكَ وَأَصْوَاتُ دُعَاتِكَ فَاغْفِرْ لِي". (د,ت)', 'ഉമ്മുസലമ(റ): മഗ്രിബ് ബാങ്ക് കേൾക്കുമ്പോൾ പറയാനായി നബി(സ) എന്നെ പഠിപ്പിച്ചു: "അല്ലാഹുവേ, ഇത് നിന്റെ രാവിന്റെ ആഗമനവും, നിന്റെ പകലിന്റെ പിൻവാങ്ങലും നിന്റെ പ്രബോധകരുടെ ശബ്ദവുമാണ്. എനിക്കു പൊറുത്തു തരേണമേ." (ദ,തു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 297, 297, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ عَلْقَمَةَ بْنِ وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِنِّي عِنْدَ مُعَاوِيَةَ إِذْ أَذَّنَ مُؤَذِّنُهُ، فَقَالَ مُعَاوِيَةُ كَمَا قَالَ الْمُؤَذِّنُ حَتَّى إِذَا قَالَ حَيَّ عَلَى الصَّلَاةِ، قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بالله، فَلَمَّا قَالَ حَيَّ عَلَى الْفَلَاحِ قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بالله، وَقَالَ بَعْدَ ذَلِكَ مَا قَالَ الْمُؤَذِّنُ، ثُمَّ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مِثْلَ ذَلِكَ (ن)', 'അൽഖമതുബ്നു വഖാസ്(റ): മുആവിയയുടെ മുഅദ്ദിൻ ബാങ്ക് വിളിക്കുമ്പോൾ ഞാൻ അടുത്തുണ്ടായിരുന്നു. ബാങ്ക് വിളിക്കുന്നയാൾ പറയുന്നപോലെ മുആവിയയും പറഞ്ഞു. ''ഹയ്യ അലസ്സലാത്'' എന്നും ''ഹയ്യ അലൽഫലാഹ്" എന്നും പറഞ്ഞപ്പോൾ മുആവിയ ''ലാഹൗല വലാഖുവ്വത ഇല്ലാബില്ലാഹി'' എന്നു പറഞ്ഞു. അതിനുശേഷം, മുഅദ്ദിൻ പറയുംപോലെയും പറഞ്ഞു.പിന്നെ പറഞ്ഞു: നബി(സ) ഇപ്രകാരം പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്. (ന)', 'عَلْقَمَةَ بْنِ وَقَّاصٍ', 'അൽഖമതുബ്നു വഖാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 297, 297, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ أَبِي أُمَامَةَ أَوْ عَنْ بَعْضِ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَضِيَ اللهُ عَنْهُمْ: أَنَّ بِلَالًا أَخَذَ فِي الْإِقَامَةِ، فَلَمَّا أَنْ قَالَ: قَدْ قَامَتِ الصَّلَاةُ قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَقَامَهَا اللهُ وَأَدَامَهَا" وَ قَالَ فِي سَائِرِ الْإِقَامَةِ كَنَحْوِ حَدِيثِ عُمَرَ رَضِيَ اللهُ عَنْهُ فِي الْأَذَانِ. (د)', 'അബൂഉമാമ(റ): അല്ലെങ്കിൽ ഏതാനും സഹാബികൾ: ബിലാൽ ഇഖാമത്ത് വിളിക്കുമ്പോൾ ''ഖദ്ഖാമതിസ്സലാത്'' എന്നു പറഞ്ഞപ്പോൾ നബി(സ): "അഖാമഹല്ലാഹു വഅദാമഹാ" (അല്ലാഹു അതു സ്ഥിരപ്പെടുത്തുകയും നിലർത്തുകയും ചെയ്യട്ടെ) എന്നു പറഞ്ഞു. ഇതല്ലാത്ത വചനങ്ങളിൽ ഉമറി(റ)ൽ നിന്ന് റിപ്പോർട്ട് ചെയ്യപ്പെട്ടതു പോലെ ബാങ്കിൽ പറയുന്നതുപോലെ തന്നെ പറഞ്ഞു. (ദ)', 'أَبِي أُمَامَةَ أَوْ عَنْ بَعْضِ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ', 'അബൂഉമാമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 297, 297, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يُرَدُّ الدُّعَاءُ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ". (د)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "ബാങ്കിനും ഇഖാമത്തിനും ഇടയിലുള്ള പ്രാർത്ഥന നിരസിക്കപ്പെടുകയില്ല." (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 298, 298, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ عَبْدِ اللهِ بْنِ مُغَفَّلٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بَيْنَ كُلِّ أَذَانَيْنِ صَلَاةٌ، بَيْنَ كُلِّ أَذَانَيْنِ صَلَاةٌ، بَيْنَ كُلِّ أَذَانَيْنِ صَلَاةٌ لِمَنْ شَاءَ". (ن)', 'അബ്ദുല്ലാഹിബ്നുമുഗഫ്ഫൽ(റ): നബി(സ) പറഞ്ഞു: "എല്ലാ രണ്ടു ബാങ്കുകൾക്കിടയിലും നിസ്കാരമുണ്ട്, എല്ലാ രണ്ടു ബാങ്കുകൾക്കിടയിലും (ബാങ്കിനും ഇഖാമത്തിനും ഇടയിൽ) നിസ്കാരമുണ്ട്, എല്ലാ രണ്ടു ബാങ്കുകൾക്കിടയിലും ഉദ്ദേശിക്കുന്നവർക്ക് നിസ്കാരമുണ്ട്.". (ന)', 'عَبْدِ اللهِ بْنِ مُغَفَّلٍ', 'അബ്ദുല്ലാഹിബ്നുമുഗഫ്ഫൽ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 298, 298, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ الْمُؤَذِّنُ إِذَا أَذَّنَ قَامَ نَاسٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَيَبْتَدِرُونَ السَّوَارِيَ يُصَلُّونَ حَتَّى يَخْرُجَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُمْ كَذَلِكَ وَيُصَلُّونَ قَبْلَ الْمَغْرِبِ وَلَمْ يَكُنْ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ شَيْءٌ. (ن)', 'അനസ്ബ്നു മാലിക്(റ): മുഅദ്ദിൻ ബാങ്ക് വിളിച്ചാൽ സഹാബികളിൽ ചിലർ എഴുന്നേറ്റുനിന്ന് പള്ളിയിലെ തൂണുകൾക്ക് മുന്നിലേക്ക് ധൃതിയിൽ പുറപ്പെടും. നബി(സ) പുറപ്പെട്ടു. വരുന്നതുവരെ സുന്നത്ത് നിസ്കരിക്കും. അവർ മഗ്രിബിന്നു മുമ്പും നിസ്കരിക്കും. ബാങ്കിനും ഇഖാമത്തിനും ഇടയിൽ മറ്റൊന്നുമുണ്ടായിരുന്നില്ല. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്ബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 298, 298, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ مِنْ آخِرِ مَا عَهِدَ إِلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أَتَّخِذَ مُؤَذِّنًا لَا يَأْخُذُ عَلَى أَذَانِهِ أَجْرًا. (د,ت,ن,جه)', 'ഉസ്മാനുബ്നു അബിൽ ആസ്(റ): നബി(സ) അവസാനമായി എന്നോടു കരാർ വാങ്ങിയത് ബാങ്കിനു പ്രതിഫലം വാങ്ങാത്ത ഒരു മുഅദ്ദിനെ നശ്ചയിക്കാനാണ്. (ദ,തു,ന,ജ)', 'عُثْمَانَ بْنِ أَبِي الْعَاصِ', 'ഉസ്മാനുബ്നു അബിൽ ആസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 298, 298, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ رَضِيَ اللهُ عَنْهُ قَالَ:قُلْتُ يَا رَسُولَ اللهِ! اجْعَلْنِي إِمَامَ قَوْمِي,فَقَالَ: "أَنْتَ إِمَامُهُمْ، وَاقْتَدِ بِأَضْعَفِهِمْ، وَاتَّخِذْ مُؤَذِّنًا لَا يَأْخُذُ عَلَى أَذَانِهِ أَجْرًا". (م,ت,ن,جه)', 'ഉസ്മാനുബ്നു അബിൽ ആസ്(റ): ഞാൻ നബി(സ)യോടു പറഞ്ഞു: എന്റെ ജനതയുടെ ഇമാമായി എന്നെ നിശ്ചയിച്ചാലും. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ അവരുടെ ഇമാമാണ്. അവരിൽ ഏറ്റവും ദുർബ്ബലരെ നീ പിന്തുടരണം. ബാങ്കിന്ന് പ്രതിഫലം വാങ്ങാത്ത ഒരു മുഅദ്ദിനെ നീ നിശ്ചയിക്കുക." (മു,തു,ന,ജ)', 'عُثْمَانَ بْنِ أَبِي الْعَاصِ', 'ഉസ്മാനുബ്നു അബിൽ ആസ്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 298, 298, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُؤَذِّنَانِ، بِلَالٌ وَابْنُ أُمِّ مَكْتُومٍ الْأَعْمَى. (م)', 'ഇബ്നുഉമർ(റ): നബി(സ)ക്ക് (മദീനയിൽ) രണ്ടു മുഅദ്ദിനുകളുണ്ടായിരുന്നു; ബിലാലും(റ) അന്ധനായ ഇബ്നുഉമ്മി മക്തൂമും(റ). (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 298, 298, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ بِلَالًا يُؤَذِّنُ بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّي يُنَادِيَ ابْنُ أُمِّ مَكْتُومٍ".وَفِي رِوَايَةٍ: "حَتَّي تَسْمَعُوا تَأْذِينَ ابْنِ أُمِّ مَكْتُومٍ".(ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "ബിലാൽ രാത്രിയിലാണ് ബാങ്ക് വിളിക്കുന്നത്. ഇബ്നുഉമ്മു മക്തൂം ബാങ്ക് വിളിക്കുംവരെ നിങ്ങൾ തിന്നുകയും കുടിക്കുകയും ചെയ്യുക." മറ്റൊരു റിപ്പോർട്ടിൽ: "ഇബ്നുഉമ്മി മക്തൂമിന്റെ ബാങ്ക് നിങ്ങൾ കേൾക്കുന്നതു വരെ." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 299, 299, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=15 and h.hadith_no=62), 1, 'وَفِي رِوَايَةٍ: "حَتَّي تَسْمَعُوا تَأْذِينَ ابْنِ أُمِّ مَكْتُومٍ".(ن)', 'മറ്റൊരു നിവേദനിൽ: "ഇബ്നുഉമ്മി മക്തൂമിന്റെ ബാങ്ക് നിങ്ങൾ കേൾക്കുന്നതു വരെ." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ ابْنَ أُمِّ مَكْتُوم كَانَ مُؤَذِّنًا لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ أَعْمَى. (م,د)', 'ആഇശ(റ): അന്ധനായ അബ്ദുല്ലാഹിബ്നു ഉമ്മുമക്തൂം നബി(സ)യുടെ ബാങ്ക് വിളിക്കാരനായിരുന്നു.(മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 299, 299, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَذَّنَ بِلَالٌ فَكُلُوا وَاشْرَبُوا حَتَّى يُؤَذِّنَ ابْنُ أُمِّ مَكْتُومٍ". قَالَتْ: وَلَمْ يَكُنْ بَيْنَهُمَا إِلَّا أَنْ يَنْزِلَ هَذَا وَيَصْعَدَ هَذَا. (ن)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "ബിലാൽ ബാങ്ക് വിളിച്ചാൽ, ഇബ്നുഉമ്മിമക്തൂം ബാങ്ക് വിളിക്കുംവരെ തിന്നുകയും കുടിക്കുകയും ചെയ്യുക." അവർ പറഞ്ഞു: ആ രണ്ടു ബാങ്കിനുമിടയിൽ ഒരാൾ കയറുകയും മറ്റൊരാൾ ഇറങ്ങുകയും ചെയ്യുന്ന വ്യത്യാസമേ ഉണ്ടായിരുന്നുള്ളൂ. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 299, 299, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أُنَيْسَةَ بِنْتِ خُبَيْبٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَذَّنَ ابْنُ أُمِّ مَكْتُومٍ فَكُلُوا وَاشْرَبُوا وَإِذَا أَذَّنَ بِلَالٌ فَلَا تَأْكُلُوا وَلَا تَشْرَبُوا (ن)', 'ഉനൈസഃബിൻത് ഖുബൈബ്(റ): നബി(സ) പറഞ്ഞു: "ഇബ്നുഉമ്മി മക്തൂം ബാങ്ക് വിളിച്ചാൽ നിങ്ങൾ തിന്നുകയും കുടിക്കുകയും ചെയ്യുക. ബിലാൽ ബാങ്ക് വിളിച്ചാൽ നിങ്ങൾ തിന്നുകയോ കുടിക്കുകയോ അരുത്." (ന)', 'أُنَيْسَةَ بِنْتِ خُبَيْبٍ', 'ഉനൈസഃബിൻത് ഖുബൈബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 299, 299, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ عَبْدِاللهِ بن عمر رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ بِلَالًا يُؤَذِّنُ بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّى يُنَادِيَ ابْنُ أُمِّ مَكْتُومٍ" ثُمَّ قَالَ: وَكَانَ رَجُلًا أَعْمَى لَا يُنَادِي حَتَّى يُقَالَ لَهُ أَصْبَحْتَ أَصْبَحْتَ. (ق,ت)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "ബിലാൽ ബാങ്ക് വിളിക്കുന്നത് രാത്രിയിലാണ്. അതിനാൽ ഇബ്നുഉമ്മുമക്തൂം ബാങ്ക് വിളിക്കുംവരെ നിങ്ങൾ തിന്നുകയും കുടിക്കുകയും ചെയ്യുക." ഇബ്നുഉമർ പറഞ്ഞു: അദ്ദേഹം അന്ധനായിരുന്നു. നേരം പുലർന്നു എന്ന് അദ്ദേഹത്തെ അറിയിക്കുന്നതുവരെ അദ്ദേഹം ബാങ്ക് വിളിക്കുകയില്ലായിരുന്നു. (ബു,മു,തു)', 'عَبْدِاللهِ بن عمر', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 299, 299, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ عَبْدِ اللهِ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَرَادَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْأَذَانِ أَشْيَاءَ لَمْ يُصْنَعْ مِنْهَا شَيْئًا، قَالَ: فَأُرِيَ عَبْدُ اللهِ بْنُ زَيْدٍ الْأَذَانَ فِي الْمَنَامِ، فَأَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ، فَقَالَ: "أَلْقِهِ عَلَى بِلَالٍ" فَأَلْقَاهُ عَلَيْهِ فَأَذَّنَ بِلَالٌ، فَقَالَ عَبْدُ اللهِ: أَنَا رَأَيْتُهُ وَأَنَا كُنْتُ أُرِيدُهُ، قَالَ: "فَأَقِمْ أَنْتَ". (د)', 'അബ്ദുല്ലാഹിബ്നു സൈദ്(റ): നബി(സ) ബാങ്കിനു വേണ്ടി എന്തെങ്കിലും ചെയ്യാനുദ്ദേശിക്കുകയും ഒന്നും ചെയ്തിട്ടില്ലാത്തതുമായ സമയം അബ്ദുല്ലാഹിബ്നു സൈദ് ബാങ്ക് സ്വപ്നത്തിൽ കണ്ടു. നബി(സ)യുടെ അടുത്ത് വന്ന് അതറിയിക്കുകയും ചെയ്തു. നബി(സ) പറഞ്ഞു: "നീയത് ബിലാലിന് പറഞ്ഞു കൊടുക്കുക. അങ്ങനെ അബ്ദുല്ലാഹിബ്നു സൈദ് ബിലാലിന് പറഞ്ഞു കൊടുത്തു. ബിലാൽ ബാങ്ക് വിളിച്ചു. അബ്ദുല്ല പറഞ്ഞു: റസൂലേ, ഞാനാണത് കണ്ടത്. അത് ഉദ്ദേശിച്ചതും ഞാൻ തന്നെ. നബി(സ) പറഞ്ഞു: "എന്നാൽ നീ ഇഖാമത്ത് കൊടുക്കുക." (ദ)', 'عَبْدِ اللهِ بْنِ زَيْدٍ', 'അബ്ദുല്ലാഹിബ്നു സൈദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 299, 299, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عن زياد بن الْحَارِثِ الصُّدَائِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا كَانَ أَوَّلُ أَذَانِ الصُّبْحِ أَمَرَنِي – يَعْنِي النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – فَأَذَّنْتُ فَجَعَلْتُ أَقُولُ: أَقِيمُ يَا رَسُولَ اللهِ! فَجَعَلَ يَنْظُرُ إِلَى نَاحِيَةِ الْمَشْرِقِ إِلَى الْفَجْرِ فَيَقُولُ: "لَا" حَتَّى إِذَا طَلَعَ الْفَجْرُ نَزَلَ فَبَرَزَ ثُمَّ انْصَرَفَ إِلَيَّ، وَقَدْ تَلَاحَقَ أَصْحَابُهُ – يَعْنِي فَتَوَضَّأَ – فَأَرَادَ بِلَالٌ أَنْ يُقِيمَ فَقَالَ لَهُ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "إِنَّ أَخَا صُدَاءٍ هُوَ أَذَّنَ، وَمَنْ أَذَّنَ فَهُوَ يُقِيمُ" قَالَ: فَأَقَمْتُ. (د,ت,جه)', 'സിയാദുബ്നു ഹാരിസുസ്സുദാഈ(റ): സുബ്ഹിന്റെ ഒന്നാമത്തെ ബാങ്കു വിളിക്കാൻ നബി(സ) എന്നോട് കൽപിച്ചു. ഞാൻ ബാങ്ക് വിളിച്ചു. പിന്നീട് ഞാൻ ചോദിച്ചു: നബിയെ, ഞാൻ ഇഖാമത്ത് കൊടുക്കട്ടെയോ? അപ്പോൾ നബി(സ) കിഴക്കു ഭാഗത്ത് പ്രഭാതത്തെ നോക്കി പറഞ്ഞു: "ആയിട്ടില്ല." പ്രഭാതം ഉദിച്ചപ്പോൾ ഇറങ്ങിവന്ന് വുളു ചെയ്തു. സഹാബികളും എത്തിച്ചേർന്നു. അപ്പോൾ ബിലാൽ ഇഖാമത്ത് കൊടുക്കാൻ ഉദ്ദേശിച്ചു. നബി(സ) പറഞ്ഞു: "സുദാഇന്റെ സഹോദരനാണ് ബാങ്ക് വിളിച്ചത്. ബാങ്ക് വിളിച്ച ആളാണ് ഇഖാമത്ത് കൊടുക്കേണ്ടത്."² സിയാദ് പറഞ്ഞു: അപ്പോൾ ഞാൻ തന്നെ ഇഖാമത്ത് വിളിച്ചു. (ദ,തു,ജ)', 'زياد بن الْحَارِثِ الصُّدَائِيِّ', 'സിയാദുബ്നു ഹാരിസുസ്സുദാഈ(റ)', '². ബാങ്ക് വിളിച്ചവർ തന്നെ ഇഖാമത്ത് വിളിക്കലാണ് ഉത്തമം എന്നാണ് ഈ ഹദീസിൽനിന്ന് മനസ്സിലാവുന്നത്. മറ്റുള്ളവർ ചെയ്യുന്നതിന് വിരോധമില്ലെന്ന് മുൻ ഹദീസിൽ നിന്ന് ഗ്രഹിക്കാം.', null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 300, 300, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ زِيَادِ بْنِ الْحَارِثِ الصُّدَائِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَأَمَرَنِي فَأَذَّنْتُ فَأَرَادَ بِلَالٌ أَنْ يُقِيمَ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "إِنَّ أَخَا صُدَاءٍ هُوَ أَذَّنَ، وَمَنْ أَذَّنَ فَهُوَ يُقِيمُ". (د,ت)', 'സിയാദുബ്നുഹാരിസ് സുദാഈ(റ): ഞാൻ നബിയോടൊപ്പം ഒരു യാത്രയിലായിരുന്നു. നബി(സ) ബാങ്ക് വിളിക്കാൻ പറഞ്ഞപ്പോൾ ഞാൻ വിളിച്ചു. ബിലാൽ(റ) ഇഖാമത്തിനുദ്ദേശിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "സുദാഇന്റെ സഹോദരനാണ് ബാങ്ക് വിളിച്ചത്, ബാങ്ക് വിളിച്ചവൻ ഇഖാമത്തും നിർവ്വഹിക്കട്ടെ." (ദ,തു)', 'زِيَادِ بْنِ الْحَارِثِ الصُّدَائِيِّ', 'സിയാദുബ്നുഹാരിസ് സുദാഈ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 300, 300, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ مُؤَذِّنُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُمْهِلُ فَلَا يُقِيمُ حَتَّى إِذَا رَأَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ خَرَجَ، أَقَامَ الصَّلَاةَ حِينَ يَرَاهُ. (م,د,ت,ن)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ)യുടെ മുഅദ്ദിൻ ഇഖാമത്ത് വിളിക്കുന്നത് താമസിപ്പിച്ചായിരുന്നു. നബി(സ) ഇറങ്ങി വരുന്നത് കണ്ടാൽ മാത്രമേ ഇഖാമത്ത് വിളിച്ചിരുന്നുള്ളൂ. (മു,ദ,തു,ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 300, 300, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أُقِيمَتِ الصَّلَاةُ فَلَا تَقُومُوا حَتَّى تَرَوْنِي" وَفِي رِوَايَةٍ: "وَعَلَيْكُمُ السَّكِينَةَ"وفي رواية: "حَتَّى تَرَوْنِي قَدْ خَرَجْتُ". (خ,د)', 'അബൂഖതാദ(റ): നബി(സ) പറഞ്ഞു: "നിസ്കാരത്തിന് ഇഖാമത്ത് കൊടുത്താൽ എന്നെ കാണുന്നതുവരെ എഴുന്നേൽക്കരുത്." മറ്റൊരു റിപ്പോർട്ടിൽ: "നിങ്ങൾ ശാന്തരായിരിക്കുക." മറ്റൊരു റിപ്പോർട്ടിൽ: "ഞാൻ വരുന്നത് നിങ്ങൾ കാണുന്നതു വരെ." (ബു,ദ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 300, 300, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=15 and h.hadith_no=71), 1, 'وَفِي رِوَايَةٍ: "وَعَلَيْكُمُ السَّكِينَةَ"', 'മറ്റൊരു നിവേദനിൽ: "നിങ്ങൾ ശാന്തരായിരിക്കുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=15 and h.hadith_no=71), 2, 'وَفِي رِوَايَةٍ: "حَتَّى تَرَوْنِي قَدْ خَرَجْتُ". (خ,د)', 'മറ്റൊരു നിവേദനിൽ: "ഞാൻ വരുന്നത് നിങ്ങൾ കാണുന്നതു വരെ." (ബു,ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ الصَّلَاةَ كَانَتْ تُقَامُ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَيَأْخُذُ النَّاسُ مَقَامَهُمْ قَبْلَ أَنْ يَأْخُذَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ (ق,د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ)യുടെ ആഗമനം പ്രതീക്ഷിച്ചാണ് നിസ്കാരത്തിന് ഇഖാമത്ത് വിളിക്കുക. അപ്പോൾ പ്രവാചകൻ(സ) എത്തുന്നതിനു മുമ്പു തന്നെ ജനങ്ങൾ (അണിയിൽ) സ്ഥലം പിടിക്കാറുണ്ടായിരുന്നു. (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 300, 301, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ حُمَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ ثَابِتًا الْبُنَانِيَّ عَنِ الرَّجُلِ يَتَكَلَّمُ بَعْدَمَا تُقَامُ الصَّلَاةُ، فَحَدَّثَنِي عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: أُقِيمَتِ الصَّلَاةُ فَعَرَضَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ فَحَبَسَهُ بَعْدَ مَا أُقِيمَتِ الصَّلَاةُ (خ,د,ن)', 'ഹുമൈദ്(റ): ഞാൻ ഥാബിതുൽ ബുനാനിയോട് ഇഖാമത്ത് വിളിച്ചശേഷം സംസാരിക്കുന്ന ഒരാളെക്കുറിച്ചു ചോദിച്ചു. അപ്പോൾ അനസുബ്നു മാലിക്(റ) പറഞ്ഞതായി അദ്ദേഹം എന്നോട് പറഞ്ഞു: ഇഖാമത്ത് വിളിച്ചപ്പോൾ നബിയുടെ മുന്നിൽ ഒരാൾ വന്നു. നിസ്കാരത്തിന് ഇഖാമത്ത് വിളിച്ചിട്ടും അയാൾ നബി(സ)യെ വൈകിപ്പിച്ചു. (ബു,ദ,ന)', 'حُمَيْدٍ', 'ഹുമൈദ്(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 301, 301, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ كَهْمَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُمْنَا إِلَى الصَّلَاةِ بِمِنًى وَالْإِمَامُ لَمْ يَخْرُجْ، فَقَعَدَ بَعْضُنَا، فَقَالَ لِي شَيْخٌ مِنْ أَهْلِ الْكُوفَةِ: مَا يُقْعِدُكَ؟ قُلْتُ: ابْنُ بُرَيْدَةَ قَالَ: هَذَا السُّمُودُ، فَقَالَ لِيَ الشَّيْخُ: حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ عَوْسَجَةَ عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَقُومُ فِي الصُّفُوفِ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ طَوِيلًا قَبْلَ أَنْ يُكَبِّرَ، قَالَ: وَقَالَ: "إِنَّ اللهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الَّذِينَ يَلُونَ الصُّفُوفَ الْأُوَلَ، وَمَا مِنْ خُطْوَةٍ أَحَبُّ إِلَى اللهِ مِنْ خُطْوَةٍ يَمْشِيهَا يَصِلُ بِهَا صَفًّا". (د,ن)', 'കഹ്മസ്(റ): ഞങ്ങൾ മിനയിലായിരിക്കെ ഇമാം എത്തുന്നതിന്നുമുമ്പ് തന്നെ നിസ്കാരത്തിനായി നിന്നു. ഞങ്ങളിൽ ചിലരാകട്ടെ ഇരിക്കുകയും ചെയ്തു. അപ്പോൾ കൂഫക്കാരനായ ഒരു വയോധികൻ എന്നോടു ചോദിച്ചു: എന്താണ് നിങ്ങൾ ഇരിക്കുന്നത്? ഞാൻ പറഞ്ഞു: ഇബ്നുബുറൈദ (കാരണം). അദ്ദേഹം പറഞ്ഞു: ഇത് തമാശ തന്നെ. അപ്പോൾ വയോധികൻ എന്നോടു പറഞ്ഞു: ബറാഉബ്നു ആസിബിൽ നിന്നും റിപ്പോർട്ട് ചെയ്തതായി അബ്ദുറഹ്മാനുബ്നു ഔസജ എന്നോട് പറഞ്ഞിട്ടുണ്ട്: ഞങ്ങൾ നബി(സ)യുടെ കാലത്ത് നിസ്കാരത്തിന് തക്ബീർ ചൊല്ലുന്നതിന് മുമ്പായി അണികളിൽ ദീർഘനേരം നിൽക്കാറുണ്ടായിരുന്നു. അദ്ദേഹം പറയുന്നു: നബി(സ) പറഞ്ഞു: "ഒന്നാമത്തെ അണിയിൽ നിൽക്കുന്നവരെ അല്ലാഹുവും അവന്റെ മലക്കുകളും പ്രകീർത്തിക്കും, ഒരു സ്വഫ്ഫിലേക്ക് ചേരാനുള്ള കാലടികളേക്കാൾ അല്ലാഹുവിന്ന് പ്രിയങ്കരമായ ഒരു കാലടിയും ഇല്ല." (ദ,ന)', 'كَهْمَسٍ', 'കഹ്മസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 301, 301, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ سَالِمٍ أَبِي النَّضْرِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ تُقَامُ الصَّلَاةُ فِي الْمَسْجِدِ إِذَا رَآهُمْ قَلِيلًا جَلَسَ لَمْ يُصَلِّ، وَإِذَا رَآهُمْ جَمَاعَةً صَلَّى. (د)', 'സാലിംഅബുന്നള്ർ(റ): പള്ളിയിൽ നിസ്കാരത്തിനായി ഇഖാമത്ത് വിളിക്കുമ്പോൾ ആളുകൾ കുറവാണെങ്കിൽ നബി(സ) നിസ്കാരമാരംഭിക്കാതിരിക്കുകയും ആളുകൾ കൂടി എന്നുകണ്ടാൽ നബി(സ) നിസ്കരിക്കുകയും ചെയ്യും. (ദ)', 'سَالِمٍ أَبِي النَّضْرِ', 'സാലിംഅബുന്നള്ർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 301, 301, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ عَبْدِ اللهِ بْنِ رُبَيِّعَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ فَسَمِعَ صَوْتَ رَجُلٍ يُؤَذِّنُ فَقَالَ مِثْلَ قَوْلِهِ، ثُمَّ قَالَ: "إِنَّ هَذَا لَرَاعِي غَنَمٍ أَوْ عَازِبٌ عَنْ أَهْلِهِ" فَنَظَرُوا فَإِذَا هُوَ رَاعِي غَنَمٍ. (ن)', 'അബ്ദുല്ലാഹിബ്നു റുബയ്യിഅഃ(റ): അദ്ദേഹം റസൂലി(സ)നോടൊപ്പം ഒരു യാത്രയിലായിരിക്കെ ഒരാൾ ബാങ്ക് വിളിക്കുന്നത് കേൾക്കുകയും നബി(സ) ആ വാക്കുകൾ ആവർത്തിക്കുകയും ചെയ്തു. എന്നിട്ട് പറഞ്ഞു: "നിശ്ചയം, അതൊരു ആട്ടിടയന്റെ ബാങ്കാണ്. അല്ലെങ്കിൽ വീടുവിട്ട് യാത്ര ചെയ്യുന്നവന്റേതാണ്." അവർ നോക്കിയപ്പോൾ അതൊരു ആട്ടിടയനായിരുന്നു. (ന)', 'عَبْدِ اللهِ بْنِ رُبَيِّعَةَ', 'അബ്ദുല്ലാഹിബ്നു റുബയ്യിഅഃ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 301, 301, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَا وَابْنُ عَمٍّ لِي وَ قَالَ مَرَّةً أُخْرَي أَنَا وَصَاحِبٌ لِي فَقَالَ: "إِذَا سَافَرْتُمَا فَأَذِّنَا وَأَقِيمَا وَلْيَؤُمَّكُمَا أَكْبَرُكُمَا". (ق,د,ت,ن,جه)', 'മാലികുബ്നുൽ ഹുവൈരിസ്(റ): ഞാനും എന്റെ ഒരു പിതൃവ്യപുത്രനും - മറ്റൊരിക്കൽ പറഞ്ഞു: ഞാനും ഒരു കൂട്ടുകാരനും - നബി(സ)യുടെ അടുക്കൽ ചെന്നപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ രണ്ടു പേർ യാത്ര ചെയ്യുമ്പോൾ നിങ്ങൾ ബാങ്കും ഇഖാമത്തും നിർവ്വഹിക്കുകയും നിങ്ങളിലെ മുതിർന്നയാൾ ഇമാമായി നിൽക്കുകയും ചെയ്യണം." (ബു,മു,ദ,തു,ന,ജ)', 'مَالِكِ بْنِ الْحُوَيْرِثِ', 'മാലികുബ്നുൽ ഹുവൈരിസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 302, 302, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ أَبِي مَحْذُورَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ حُنَيْنٍ خَرَجْتُ عَاشِرَ عَشَرَةٍ مِنْ أَهْلِ مَكَّةَ نَطْلُبُهُمْ، فَسَمِعْنَاهُمْ يُؤَذِّنُونَ بِالصَّلَاةِ، فَقُمْنَا نُؤَذِّنُ نَسْتَهْزِئُ بِهِمْ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "قَدْ سَمِعْتُ فِي هَؤُلَاءِ تَأْذِينَ إِنْسَانٍ حَسَنِ الصَّوْتِ" فَأَرْسَلَ إِلَيْنَا فَأَذَّنَّا رَجُلٌ رَجُلٌ وَكُنْتُ آخِرَهُمْ فَقَالَ حِينَ أَذَّنْتُ: ''تَعَالَ'' فَأَجْلَسَنِي بَيْنَ يَدَيْهِ فَمَسَحَ عَلَى نَاصِيَتِي، وَبَرَّكَ عَلَيَّ ثَلَاثَ مَرَّاتٍ، ثُمَّ قَالَ: "اذْهَبْ، فَأَذِّنْ عِنْدَ الْبَيْتِ الْحَرَامِ" قُلْتُ: كَيْفَ يَا رَسُولَ اللهِ؟ فَعَلِّمْنِي كَمَا تُؤَذِّنُونَ الْآنَ بِهَا: "اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الْفَلَاحِ، حَيَّ عَلَى الْفَلَاحِ، الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ فِي الْأُولَى مِنَ الصُّبْحِ، قَالَ: وَعَلَّمَنِي الْإِقَامَةَ مَرَّتَيْنِ: اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الْفَلَاحِ، حَيَّ عَلَى الْفَلَاحِ، قَدْ قَامَتِ الصَّلَاةُ، قَدْ قَامَتِ الصَّلَاةُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللَّهُ". (ن)', 'അബൂമഹ്ദൂറ(റ): നബി(സ) ഹുനൈനിൽ നിന്നും പുറപ്പെട്ടപ്പോൾ മക്കയിൽനിന്നുള്ള പത്തിലൊരാളായി അവരെ അന്വേഷിച്ച് ഞാനും പുറപ്പെട്ടു. അപ്പോൾ അവർ ബാങ്ക് വിളിക്കുന്നതായി ഞങ്ങൾ കേട്ടു. അവരെ പരിഹസിച്ച് ഞങ്ങളും ബാങ്ക് വിളിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അതിൽ നല്ല ശബ്ദ മാധുര്യമുള്ള ഒരാളുടെ ബാങ്ക് ഞാൻ കേട്ടു." അങ്ങനെ ഞങ്ങളിലോരോരുത്തരായി പ്രവാചകന്റെ മുന്നിൽ ബാങ്ക് കേൾപ്പിച്ചു. ഞാനവരിൽ അവസാനത്തെ ആളായിരുന്നു. ഞാൻ ബാങ്ക് വിളിച്ചപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "വരൂ". എന്നിട്ട് എന്നെ പ്രവാചകൻ(സ) മുന്നിലിരുത്തി. എന്റെ തലയിൽ തലോടി, എന്നെ മൂന്നുപ്രാവശ്യം അനുഗ്രഹിച്ചു. തുടർന്നുപറഞ്ഞു: "നീ ബൈതുൽ ഹറാമിങ്കൽ ചെന്ന് ബാങ്ക് വിളിക്കുക." ഞാൻ ചോദിച്ചു: പ്രവാചകരേ എപ്രകാരമാണ് (ബാങ്ക് വിളിക്കേണ്ടത്)? അങ്ങനെ, നിങ്ങൾ ഇപ്പോൾ വിളിക്കുന്നതു പോലെയുള്ള ബാങ്ക് നബി(സ) ഇപ്രകാരം എന്നെ പഠിപ്പിച്ചു: അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ. അശ്ഹദു അൻലാ ഇലാഹ ഇല്ലല്ലാഹ്, അശ്ഹദു അൻലാ ഇലാഹ ഇല്ലല്ലാഹ്. അശ്ഹദു അന്നമുഹമ്മദൻ റസൂലുല്ലാഹ്, അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാഹ്. അശ്ഹദു അൻലാ ഇലാഹ ഇല്ലല്ലാഹ്, അശ്ഹദു അൻലാ ഇലാഹ ഇല്ലല്ലാഹ്. അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാഹ്, അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാഹ്. ഹയ്യ അല സ്സ്വലാത്, ഹയ്യ അലസ്സ്വലാത്. ഹയ്യ അലൽ ഫലാഹ്, ഹയ്യ അലൽ ഫലാഹ്. സുബഹിന്റെ ഒന്നാമത്തെ ബാങ്കിൽ; അസ്സ്വലാതു ഖൈറുമ്മിനന്നൗം, അസ്സ്വലാതു ഖൈറുമ്മിനന്നൗം. അദ്ദേഹം തുടരുന്നു: ഇഖാമത്ത് ഈരണ്ടായി എന്നെ ഇപ്രകാരം പഠിപ്പിച്ചു; അല്ലാഹു അക്ബർ അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ അല്ലാഹു അക്ബർ. അശ്ഹദു അൻലാഇലാഹ ഇല്ലല്ലാഹ്, അശ്ഹദു അൻലാഇലാഹ ഇല്ലല്ലാഹ്. അശ്ഹദു അന്നമുഹമ്മദൻ റസൂലുല്ലാഹ്, അശ്ഹദു അന്നമുഹമ്മദൻ റസൂലുല്ലാഹ്. ഹയ്യ അലസ്സ്വലാത്, ഹയ്യ അലസ്സ്വലാത്. ഹയ്യ അലൽ ഫലാഹ്, ഹയ്യ അലൽ ഫലാഹ്. ഖദ്ഖാമതിസ്സ്വലാത്, ഖദ്ഖാമതിസ്സ്വലാത്. അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ. ലാഇലാഹ ഇല്ലല്ലാഹ്. (ന)', 'أَبِي مَحْذُورَةَ', 'അബൂമഹ്ദൂറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 302, 303, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ مُعَاذِ بْنِ جَبَلٍ قَالَ: أُحِيلَتِ الصَّلَاةُ ثَلَاثَةَ أَحْوَالٍ، وَأُحِيلَ الصِّيَامُ ثَلَاثَةَ أَحْوَالٍ، وَسَاقَ نَصْرٌ الْحَدِيثَ بطوله وَاقْتَصَّ ابْنُ الْمُثَنَّى مِنْهُ قِصَّةَ صلاتهم نَحْوَ بَيْتِ الْمَقْدِسِ، قَالَ الْحَالُ الثَّالِثُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدِمَ الْمَدِينَةَ فَصَلَّى — يَعْنِي نَحْوَ بَيْتِ الْمَقْدِسِ ثَلَاثَةَ عَشَرَ شَهْرًا، فَأَنْزَلَ اللهُ تَعَالَى هَذِهِ الْآيَةَ: {قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ} فَوَجَّهَهُ اللهُ تَعَالَى إِلَى الْكَعْبَةِ، وَتَمَّ حديثه وسمى نَصْرٌ صَاحِبَ الرُّؤْيَا قَالَ: فَجَاءَ عَبْدُ اللهِ بْنُ زَيْدٍ رَجُلٌ مِنَ الْأَنْصَارِ وَقَالَ فِيهِ، فَاسْتَقْبَلَ الْقِبْلَةَ قَالَ: اللهُ أَكْبَرُ اللهُ أَكْبَرُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، حَيَّ عَلَى الصَّلَاةِ مَرَّتَيْنِ، حَيَّ عَلَى الْفَلَاحِ مَرَّتَيْنِ، اللهُ أَكْبَرُ اللهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللهُ، ثُمَّ أَمْهَلَ هُنَيَّةً، ثُمَّ قَامَ فَقَالَ مِثْلَهَا إِلَّا أَنَّهُ قَالَ: زَادَ بَعْدَ مَا قَالَ: حَيَّ عَلَى الْفَلَاحِ، قَدْ قَامَتِ الصَّلَاةُ قَدْ قَامَتِ الصَّلَاةُ، قَالَ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَقِّنْهَا بِلَالًا". فَأَذَّنَ بِهَا بِلَالٌ. وَ قَالَ فِي الصَّوْمِ قَالَ: فَإِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَصُومُ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ، وَيَصُومُ يَوْمَ عَاشُورَاءَ فَأَنْزَلَ اللهُ تَعَالَى: {كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ} إِلَى قَوْلِهِ {طَعَامُ مِسْكِينٍ} فَمَنْ شَاءَ أَنْ يَصُومَ صَامَ، وَمَنْ شَاءَ أَنْ يُفْطِرَ وَيُطْعِمَ كُلَّ يَوْمٍ مِسْكِينًا، أَجْزَأَهُ ذَلِكَ، وَهَذَا حَوْلٌ فَأَنْزَلَ اللهُ تَعَالَى {شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ} إِلَى {أَيَّامٍ أُخَرَ} فَثَبَتَ الصِّيَامُ عَلَى مَنْ شَهِدَ الشَّهْرَ، وَعَلَى الْمُسَافِرِ أَنْ يَقْضِيَ، وَثَبَتَ الطَّعَامُ لِلشَّيْخِ الْكَبِيرِ وَالْعَجُوزِ اللَّذَيْنِ لَا يَسْتَطِيعَانِ الصَّوْمَ وَجَاءَ صِرْمَةُ وَقَدْ عَمِلَ يَوْمَهُ وَسَاقَ الْحَدِيثَ. (د)', 'മുആദുബ്നു ജബൽ(റ): നിസ്കാരത്തിന് മൂന്നു പ്രാവശ്യം മാറ്റങ്ങളുണ്ടായി, നോമ്പിനും മൂന്നു പ്രാവശ്യം മാറ്റങ്ങളുണ്ടായി. നീണ്ട ഈ ഹദീസ് നസ്ർ ഉദ്ധരിച്ചതാണ്. അവർ ബൈതുൽ മുഖദ്ദസിനു നേരെ തിരിഞ്ഞ് നിസ്കരിച്ച സംഭവം ഇബ്നുൽ മുസന്ന അദ്ദേഹത്തിൽനിന്ന് വിവരിച്ചു. മൂന്നാമത്തെ ഘട്ടമിതാണ്: പ്രവാചൻ(സ) മദീനയിലേക്കു വന്ന് ബൈതുൽ മുഖദ്ദസിലേക്കു തിരിഞ്ഞ് പതിമൂന്ന് മാസം നിസ്കരിച്ചു. അപ്പോൾ അല്ലാഹു ഖുർആൻ അവതരിപ്പിച്ചു: നിന്റെ മുഖം ആകാശത്തേക്കു തിരിയുന്നത് ഞാൻ കാണുന്നു. അതിനാൽ നീ തൃപ്തിപ്പെടുന്ന ഖിബ്ലയിലേക്കു നാം നിന്നെ തിരിക്കുക തന്നെ ചെയ്യും. അപ്പോൾ നീ നിന്റെ മുഖം മസ്ജിദുൽ ഹറാമിന്റെ ഭാഗത്തേക്കു തിരിക്കുക, നിങ്ങൾ എവിടെയായിരുന്നാലും നിങ്ങളുടെ മുഖത്തെ അതിനു നേരെ തിരിക്കുക. (അൽബഖറ: 144) അങ്ങനെ പ്രവാചകൻ(സ)യെ അല്ലാഹു കഅ്ബയുടെ ഭാഗത്തേക്കു തിരിച്ചു. അൻസ്വാരിയായ അബ്ദുല്ലാഹിബ്നു സൈദ് വന്നു. അദ്ദേഹം ഖിബ്ലക്കഭിമുഖമായി നിന്ന് പറഞ്ഞു: അല്ലാഹു അക്ബർ അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ, അശ്ഹദു അൻലാഇലാഹ ഇല്ലല്ലാഹു, അശ്ഹദു അൻലാഇലാഹ ഇല്ലല്ലാഹു, അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാ, അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാ, ഹയ്യഅലസ്സ്വലാത്ത്, ഹയ്യ അലസ്സ്വലാത്ത്, ഹയ്യഅലൽ ഫലാഹ്, ഹയ്യഅലൽ ഫലാഹ്, അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ, ലാഇലാഹ ഇല്ലല്ലാഹ്. പിന്നെ കുറച്ചു താമസിച്ച ശേഷം വീണ്ടും എഴുന്നേറ്റു നിന്ന് അതുപോലെ പറഞ്ഞു. ഹയ്യ അലൽ ഫലാഹ് എന്നതിനു ശേഷം ഖദ്ഖാമതിസ്സ്വലാത്, ഖദ്ഖാമതിസ്സ്വലാത് എന്നാണ് പറഞ്ഞത്. അപ്പോൾ പ്രവാചൻ(സ) പറഞ്ഞു: ഇത് ബിലാലിന് പറഞ്ഞു കൊടുക്കുക. അങ്ങനെ അതുകൊണ്ട് ബിലാൽ ബാങ്കു വിളിച്ചു. നോമ്പിന്റെ കാര്യത്തിൽ അദ്ദേഹം പറഞ്ഞു: പ്രവാചൻ(സ) ഓരോ മാസവും മൂന്നു ദിവസം നോമ്പനുഷ്ഠിക്കാറുണ്ടായിരുന്നു. ആശൂറാഅ് (മുഹർറം പത്ത്) നോമ്പും അനുഷ്ടിക്കാറുണ്ടായിരുന്നു. അങ്ങനെ ഖുർആനിലെ: "നിങ്ങളുടെ മുൻ ഗാമികൾക്കു നിർബന്ധമാക്കപ്പെട്ടപോലെ നിങ്ങൾക്കും നോമ്പ് നിർബന്ധമാക്കിയിരിക്കുന്നു......" എന്നു തുടങ്ങുന്ന സൂറത്തുൽബഖറയിലെ നൂറ്റി എൺപത്തിമൂന്ന്, നൂറ്റി എൺപത്തിനാല് സൂക്തങ്ങൾ അവതരിച്ചു. അപ്പോൾ നോമ്പെടുക്കാനുദ്ദേശിച്ചവർ നോമ്പെടുത്തു. നോമ്പെടുക്കാതെ ദിവസവും പാവപ്പെട്ടവർക്ക് ഭക്ഷണം നൽകുന്നവന് അതു മതിയായിരുന്നു. ഇതൊരു മാറ്റമായിരുന്നു. അപ്പോഴാണ്: "റമദാൻ മാസത്തിലാണ് ഖുർആൻ ഇറങ്ങിയത്......." എന്നു തുടങ്ങുന്ന സൂറഃ അൽ ബഖറയിലെ 185 ാം സൂക്തം അവതരിച്ചത്. അങ്ങനെ ആ മാസത്തിൽ പങ്കെടുത്തവന് നോമ്പ് നിർബന്ധമായി. യാത്രക്കാരന് നോമ്പ് പിന്നീട് വീട്ടണമെന്നുമായി. നോമ്പനുഷഠിക്കാൻ സാധിക്കാത്ത കിഴവിക്കും വൃദ്ധനും ഭക്ഷണം നൽകൽ നിർബന്ധമായി...... ഹദീസ് തുടർന്നു പറഞ്ഞു.) (ദ)', 'مُعَاذِ بْنِ جَبَلٍ قَالَ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 303, 304, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَأْمُرُ مُؤَذِّنًا يُؤَذِّنُ ثُمَّ يَقُولُ عَلَى إِثْرِهِ "أَلَا صَلُّوا فِي الرِّحَالِ فِي اللَّيْلَةِ الْبَارِدَةِ أَوِ الْمَطِيرَةِ فِي السَّفَرِ". (خ)', 'ഇബ്നുഉമർ(റ): നബി(സ) ബാങ്ക് വിളിക്കുന്നയാളോട് ബാങ്കിനു കൽപിച്ചു. അതിനെത്തുടർന്ന് ഇപ്രകാരം പറഞ്ഞു: "നിങ്ങൾ യാത്രയിലായിരിക്കെ തണുത്ത രാത്രിയിലായാലും മഴയുള്ള രാത്രിയിലായാലും താവളത്തിൽ തന്നെ നിസ്കരിക്കുക." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 304, 304, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْنَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَنَحْنُ شَبَبَةٌ مُتَقَارِبُونَ، فَأَقَمْنَا عِنْدَهُ عِشْرِينَ لَيْلَةً، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَحِيمًا رَفِيقًا، فَظَنَّ أَنَّا قَدِ اشْتَقْنَا إِلَى أَهْلِنَا، فَسَأَلَنَا عَمَّنْ تَرَكْنَاهُ مِنْ أَهْلِنَا، فَأَخْبَرْنَاهُ، فَقَالَ: "ارْجِعُوا إِلَى أَهْلِيكُمْ، فَأَقِيمُوا عِنْدَهُمْ، وَعَلِّمُوهُمْ، وَمُرُوهُمْ إِذَا حَضَرَتِ الصَّلَاةُ، فَلْيُؤَذِّنْ لَكُمْ أَحَدُكُمْ، وَلْيَؤُمَّكُمْ أَكْبَرُكُمْ". (ن,خ) وَفِي رِوَايَةٍ قَالَ: أَتَى رَجُلَانِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُرِيدَانِ السَّفَرَ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَنْتُمَا خَرَجْتُمَا فَأَذِّنَا، ثُمَّ أَقِيمَا، ثُمَّ لِيَؤُمَّكُمَا أَكْبَرُكُمَا". (خ)', 'മാലികുബ്നുൽ ഹുവൈരിസ്(റ): ഞങ്ങൾ നബി(സ)യുടെ അടുത്തുചെന്നു. പ്രായത്തിൽ ഏതാണ്ട് സമന്മാരായിരുന്നു ഞങ്ങൾ. ഞങ്ങൾ നബി(സ)യുടെ അടുത്ത് ഇരുപത് രാവുകൾ താമസിച്ചു. നബി(സ) കാരുണ്യവാനും ആത്മസുഹൃത്തുമായിരുന്നു. ഞങ്ങൾ ഞങ്ങളുടെ കുടുംബത്തിലേക്ക് മടങ്ങാൻ ആഗ്രഹിക്കുന്നതായി നബി(സ)ക്കു തോന്നി. ഞങ്ങളുടെ കുടുംബ കാര്യങ്ങൾ നബി(സ) ചോദിച്ചു. ഞങ്ങൾ അദ്ദേഹത്തെ വിവരങ്ങൾ അറിയിച്ചപ്പോൾ തിരുമേനി അരുളി: "നിങ്ങൾ നിങ്ങളുടെ കുടുംബത്തിലേക്കു തിരിച്ചുചെല്ലുക. അവരുടെയടുത്തു താമസിക്കുകയും അവരെ പഠിപ്പിക്കുകയും ചെയ്യുക. നിസ്കാര സമയമായാൽ അവരോട് ഇപ്രകാരം കൽപിക്കുക: നിങ്ങളിൽ നിന്നൊരാൾ ബാങ്കു വിളിക്കുക. നിങ്ങളിൽ ഏറ്റവും മുതിർന്ന ആൾ ഇമാമായി നിൽക്കുക." (ന,ബു)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=15 and h.hadith_no=81), 1, 'وَفِي رِوَايَةٍ قَالَ: أَتَى رَجُلَانِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُرِيدَانِ السَّفَرَ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَنْتُمَا خَرَجْتُمَا فَأَذِّنَا، ثُمَّ أَقِيمَا، ثُمَّ لِيَؤُمَّكُمَا أَكْبَرُكُمَا". (خ)', 'മറ്റൊരു നിവേദനിൽ: യാത്ര ഉദ്ദേശിച്ച് നബി(സ)യുടെ അടുത്ത് രണ്ടാളുകൾ വന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പുറപ്പെട്ടാൽ ബാങ്കും, ഇഖാമത്തും വിളിക്കുക. പിന്നെ രണ്ടിൽ പ്രായം കൂടുതലുള്ളയാൾ ഇമാമത്ത് നിൽക്കുകയും ചെയ്യുക." (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ أَيُّوبَ عَنْ أَبِي قِلَابَةَ عَنْ عَمْرِو بْنِ سَلَمَةَ رَضِيَ اللهُ عَنْهُمْ فَقَالَ لِي أَبُو قِلَابَةَ: هُوَ حَيٌّ، أَفَلَا تَلْقَاهُ؟ قَالَ أَيُّوبُ: فَلَقِيتُهُ، فَسَأَلْتُهُ، فَقَالَ: لَمَّا كَانَ وَقْعَةُ الْفَتْحِ بَادَرَ كُلُّ قَوْمٍ بِإِسْلَامِهِمْ، فَذَهَبَ أَبِي بِإِسْلَامِ أَهْلِ حَوَائِنَا، فَلَمَّا قَدِمَ اسْتَقْبَلْنَاهُ فَقَالَ: جِئْتُكُمْ وَاللهِ مِنْ عِنْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَقًّا، فَقَالَ: "صَلُّوا صَلَاةَ كَذَا فِي حِينِ كَذَا، وَصَلَاةَ كَذَا فِي حِينِ كَذَا، فَإِذَا حَضَرَتِ الصَّلَاةُ فَلْيُؤَذِّنْ لَكُمْ أَحَدُكُمْ، وَلْيَؤُمَّكُمْ أَكْثَرُكُمْ قُرْآنًا". (ن)', 'അംറുബ്നു അബീസലമ(റ), അബൂഖിലാബയിൽ നിന്ന് അയ്യൂബ്: (ഈ ഹദീസ് ഉദ്ധരിച്ചു തരുമ്പോൾ) അബൂഖിലാബഃ എന്നോട് പറഞ്ഞു: അദ്ദേഹം (അംറുബ്നു സലമഃ) ജീവിച്ചിരിക്കുന്നുണ്ടല്ലോ? അദ്ദേഹത്തെ നിനക്കൊന്ന് കണ്ടുകൂടേ? അയ്യൂബ് പറഞ്ഞു: അങ്ങനെ ഞാൻ അദ്ദേഹത്തെ കാണുകയും ചോദിക്കുകയും ചെയ്തു. അപ്പോൾ പറഞ്ഞു: മക്കാവിജയം നടന്നപ്പോൾ ജനതകൾ ഇസ്ലാം പ്രഖ്യാപിച്ചു മുന്നോട്ടുവന്നു. ഞങ്ങളുടെ ഗ്രാമക്കാരുടെ ഇസ്ലാം വിശ്വാസമറിയിക്കാൻ എന്റെ പിതാവും ചെന്നു. അദ്ദേഹം വന്നപ്പോൾ ഞങ്ങൾ അദ്ദേഹത്തെ സ്വീകരിച്ചു. അപ്പോൾ പറഞ്ഞു: അല്ലാഹുവാണെ! ഞാൻ അല്ലാഹുവിന്റെ ദൂതന്റെ അടുത്തുനിന്നാണു വരുന്നത്. പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങൾ ഇപ്രകാരം ഇന്നിന്ന സമയങ്ങളിൽ നിസ്കരിക്കുക. നിസ്കാര സമയമായാൽ നിങ്ങളിലൊരാൾ ബാങ്കു വിളിക്കണം. നിങ്ങളിൽ ഖുർആൻ കൂടുതലായി അറിയാവുന്നയാൾ ഇമാമാകണം." (ന)', 'أَيُّوبَ عَنْ أَبِي قِلَابَةَ عَنْ عَمْرِو بْنِ سَلَمَةَ', 'അംറുബ്നു അബീസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 304, 305, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عن حفصة رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا اعْتَكَفَ الْمُؤَذِّنُ لِلصُّبْحِ وَبَدَا الصُّبْحُ صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ قَبْلَ أَنْ تُقَامَ الصَّلَاةُ. (خ)', 'ഹഫ്സ(റ): മുഅദ്ദിൻ സുബ്ഹ് ബാങ്കിനുവേണ്ടി ഒരുങ്ങുകയും പ്രഭാതം വെളിവാകുകയും ചെയ്താൽ നിസ്കാരത്തിന് ഇഖാമത്തു വിളിക്കുന്നതിനു മുമ്പായി നബി(സ) ലഘുവായി രണ്ട് റകഅത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. (ബു)', 'حفصة', 'ഹഫ്സ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 305, 305, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ عَبْدِاللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَمْنَعَنَّ أَحَدَكُمْ أَوْ أَحَدًا مِنْكُمْ أَذَانُ بِلَالٍ مِنْ سَحُورِهِ فَإِنَّهُ يُؤَذِّنُ أَوْ يُنَادِي بِلَيْلٍ لِيَرْجِعَ قَائِمَكُمْ وَلِيُنَبِّهَ نَائِمَكُمْ وَلَيْسَ أَنْ يَقُولَ الْفَجْرُ أَوِ الصُّبْحُ" وَقَالَ بِأَصَابِعِهِ وَرَفَعَهَا إِلَى فَوْقُ، وَطَأْطَأَ إِلَى أَسْفَلُ، حَتَّى يَقُولَ: هَكَذَا، وَقَالَ زُهَيْرٌ بِسَبَّابَتَيْهِ إِحْدَاهُمَا فَوْقَ الْأُخْرَى ثُمَّ مَدَّهَا عَنْ يَمِينِهِ وَشِمَالِهِ. (خ)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരെയും ബിലാലിന്റെ ബാങ്ക് അത്താഴം കഴിക്കുന്നതിൽനിന്ന് തടയേണ്ടതില്ല. കാരണം ആ ബാങ്ക് രാത്രിയിലാണ്. എഴുന്നേറ്റു പോയവർ തിരിച്ചുവരാനും ഉറങ്ങുന്നവരെ ഉണർത്താനുമാണത്. ഫജ്റ് ആയി എന്നോ സുബ്ഹി ആയി എന്നോ അറിയിക്കാനല്ല. തുടർന്നു വിരലുകൊണ്ടു ചൂണ്ടിക്കാണിച്ചു. വിരലുകൾ മുകളിലേക്കുയർത്തിയ ശേഷം താഴേക്ക് മെല്ലെ താഴ്ത്തി. സുഹൈർ തന്റെ രണ്ടു ചൂണ്ടുവിരലുകൾ ഒന്നിനു മുകളിൽ ഒന്നായി ചൂണ്ടിക്കാണിച്ചു വലത്തോട്ടും ഇടത്തോട്ടും നീട്ടി. (ബു)', 'عَبْدِاللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 305, 305, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "يَعْجَبُ رَبُّكَ مِنْ رَاعِي غَنَمٍ فِي رَأْسِ شَظِيَّةِ الْجَبَلِ يُؤَذِّنُ بِالصَّلَاةِ وَيُصَلِّي، فَيَقُولُ اللهُ عَزَّ وَجَلَّ: انْظُرُوا إِلَى عَبْدِي هَذَا يُؤَذِّنُ وَيُقِيمُ الصَّلَاةَ يَخَافُ مِنِّي، قَدْ غَفَرْتُ لِعَبْدِي، وَأَدْخَلْتُهُ الْجَنَّةَ". (ن)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "പർവ്വതത്തിന്റെ മുകളിലെ ഒരാട്ടിടയന്റെ കാര്യത്തിൽ അല്ലാഹു അത്ഭുതപ്പെടുന്നു. അയാൾ ബാങ്ക് വിളിക്കുകയും നിസ്കരിക്കുകയും ചെയ്യുന്നു. അപ്പോൾ അല്ലാഹു പറയും: നിങ്ങൾ എന്റെ ഈ അടിമയെ നോക്കൂ. ബാങ്കു വിളിക്കുകയും നിസ്കാരം നിലനിർത്തുകയും ചെയ്യുന്നു, അവൻ എന്നെ ഭയപ്പെടുന്നു. ഞാൻ എന്റെ ആ അടിമക്കു പൊറുത്തു കൊടുക്കുകയും അവനെ സ്വർഗ്ഗസ്ഥനാക്കുകയും ചെയ്തിരിക്കുന്നു." (ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 305, 305, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ بِلَالًا أَذَّنَ قَبْلَ طُلُوعِ الْفَجْرِ، فَأَمَرَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَرْجِعَ فَيُنَادِيَ: أَلَا إِنَّ الْعَبْدَ قَدْ نَامَ، أَلَا إِنَّ الْعَبْدَ قَدْ نَامَ. (د,ت)', 'ഇബ്നുഉമർ(റ): ഒരിക്കൽ ബിലാൽ പ്രഭാതോദയത്തിനു മുമ്പായി ബാങ്കു വിളിച്ചപ്പോൾ നബി(സ) ബിലാലിനോടു വീണ്ടും ഇപ്രകാരം വിളിച്ചു പറയാൻ കൽപിച്ചു ''അലാ ഇന്നൽ അബ്ദ ഖദ് നാമ, അലാ ഇന്നൽ അബ്ദ ഖദ് നാമ'' (അറിയുക നിശ്ചയം അല്ലാഹുവിന്റെ അടിമ ഉറങ്ങിപ്പോയി.) (ദ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 306, 306, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ بِلَالٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "لَا تُؤَذِّنْ حَتَّى يَسْتَبِينَ لَكَ الْفَجْرُ هَكَذَا" وَمَدَّ يَدَيْهِ عَرْضًا. (د)', 'ബിലാൽ(റ): നബി(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "പ്രഭാതം ഈവിധം ദൃശ്യമാകുന്നതുവരെ നീ ബാങ്കു വിളിക്കരുത്."നബി(സ) അവിടുത്തെ കൈകൾ വിലങ്ങനെ കാണിച്ചു കൊണ്ടായിരുന്നു ഇത് പറഞ്ഞത്. (ദ)', 'بِلَالٍ', 'ബിലാൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 306, 306, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ أَبِي الشَّعْثَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ أَبِي هُرَيْرَةَ فِي الْمَسْجِدِ فَخَرَجَ رَجُلٌ حِينَ أَذَّنَ الْمُؤَذِّنُ لِلْعَصْرِ، فَقَالَ أَبُو هُرَيْرَةَ: أَمَّا هَذَا فَقَدْ عَصَى أَبَاالْقَاسِمِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,د,ت,ن جه)', 'അബുശഅ്സാഅ്(റ): അബൂഹുറൈറ(റ)യോടൊപ്പം ഞങ്ങൾ പള്ളിയിലായിരിക്കെ മുഅദ്ദിൻ അസ്റിനു ബാങ്ക് വിളിച്ചപ്പോൾ ഒരാൾ പുറത്തേക്കു പോയി. അപ്പോൾ അബൂഹുറൈറ(റ) പറഞ്ഞു: ഇയാൾ അബൂൽ ഖാസിം(സ)യുടെ ചര്യ ലംഘിച്ചിരിക്കുന്നു. (മു,ദ,തു,ന,ജ)', 'أَبِي الشَّعْثَاءِ', 'അബുശഅ്സാഅ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 306, 306, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَدْرَكَهُ الْأَذَانُ فِي الْمَسْجِدِ ثُمَّ خَرَجَ لَمْ يَخْرُجْ لِحَاجَةٍ وَهُوَ لَا يُرِيدُ الرَّجْعَةَ فَهُوَ مُنَافِقٌ". (جه)', 'ഉസ്മാൻ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ പള്ളിയിലായിരിക്കെ ബാങ്ക് കേൾക്കുകയും പിന്നീടു ശാരീരികാവശ്യങ്ങൾക്കല്ലാതെ പുറത്തു പോകുകയും ചെയ്താൽ അവൻ മടങ്ങിവരാൻ ഉദ്ദേശിക്കുന്നില്ലെങ്കിൽ അവൻ കപട വിശ്വാസിയാണ്." (ജ)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 306, 306, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا غَزَا بِنَا قَوْمًا لَمْ يَكُنْ يَغْزُو بِنَا حَتَّى يُصْبِحَ وَيَنْظُرَ، فَإِنْ سَمِعَ أَذَانًا كَفَّ عَنْهُمْ، وَإِنْ لَمْ يَسْمَعْ أَذَانًا أَغَارَ عَلَيْهِمْ. (خ)', 'അനസുബ്നു മാലിക് (റ): ഞങ്ങളെയുമായി ഏതെങ്കിലും സമുദായത്തോട് യുദ്ധം ചെയ്യാൻ പോകുന്ന സമയത്ത് നബി(സ) പ്രഭാതമാവുംവരെ പ്രതീക്ഷിക്കുകയും, ബാങ്ക് കേൾക്കുന്നുണ്ടോ എന്ന് ശ്രദ്ധിക്കുകയും, ബാങ്ക് കേൾക്കുന്നുണ്ടെങ്കിൽ അവരോട് യുദ്ധം ചെയ്യാതിരിക്കുകയും, കേൾക്കുന്നില്ലെങ്കിൽ യുദ്ധം ചെയ്യുകയും ചെയ്യുമായിരുന്നു. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക് (റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 306, 306, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أُقِيمَتِ الصَّلَاةُ، وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُنَاجِي رَجُلًا فِي جَانِبِ الْمَسْجِدِ، فَمَا قَامَ إِلَى الصَّلَاةِ حَتَّى نَامَ الْقَوْمُ. (خ)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ഒരാളുമായി പള്ളിയുടെ ഒരുഭാഗത്ത് സംസാരിച്ചു കൊണ്ടിരിക്കെ ഇഖാമത്ത് വിളിക്കപ്പെട്ടു. ജനങ്ങൾ ഉറങ്ങും വരെ നബി(സ) നിസ്കരിക്കാൻ നിന്നില്ല. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 306, 307, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ ابْنَ أُمِّ مَكْتُوم كَانَ مُؤَذِّنًا لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ أَعْمَى. (م,د)', 'ആഇശ(റ): അന്ധനായ അബ്ദുല്ലാഹിബ്നു ഉമ്മിമകതൂം റസൂലി(സ)ന്റെ ബാങ്ക് വിളിക്കാരനായിരുന്നു. (മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 307, 307, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ مُجَاهِدٍ قَالَ: كُنْتُ مَعَ ابْنِ عُمَرَ فَثَوَّبَ رَجُلٌ فِي الظُّهْرِ أَوِ الْعَصْرِ، قَالَ: اخْرُجْ بِنَا، فَإِنَّ هَذِهِ بِدْعَةٌ. (د,ت)', 'മുജാഹിദ്(റ): ഞാൻ ഇബ്നുഉമറിന്റെ കൂടെ ആയിരുന്നപ്പോൾ ഒരാൾ ദുഹ്റിലോ – അല്ലെങ്കിൽ അസ്റിലോ – തസ്വീബ് ചൊല്ലി. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നീ ഞങ്ങളുടെ അടുത്ത് നിന്നു പോകൂ! ഇത് ബിദ്അത്താണ്. (ദ,തു)', 'مُجَاهِدٍ قَالَ', 'മുജാഹിദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 307, 307, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ أَبِي مَحْذُورَةَ: خَرَجْتُ فِي نَفَرٍ فَكُنَّا ببعض طريق فَأَذَّنَ مُؤَذِّنُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بالصلاة عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَسَمِعْنَا صَوْتَ الْمُؤَذِّنِ، وَنَحْنُ عَنْهُ مُتَنَكِّبُونَ فَظَلَلْنَا نَحْكِيهِ وَنَهْزَأُ بِهِ، فَسَمِعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الصَّوْتَ، فَأَرْسَلَ إِلَيْنَا حَتَّى وَقَفْنَا بَيْنَ يَدَيْهِ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَيُّكُمُ الَّذِي سَمِعْتُ صَوْتَهُ قَدِ ارْتَفَعَ". فَأَشَارَ الْقَوْمُ إِلَيَّ، وَصَدَقُوا، فَأَرْسَلَهُمْ كُلَّهُمْ وَحَبَسَنِي فَقَالَ: "قُمْ فَأَذِّنْ بالصلاة" فَقُمْتُ فَأَلْقَى عَلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ التَّأْذِينَ هُوَ بنفسه قَالَ: "قُلِ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ" ثُمَّ قَالَ: "ارجع فامدد صوتك" ثُمَّ قَالَ: "قل أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، حَيَّ عَلَى الصَّلَاةِ حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الْفَلَاحِ حَيَّ عَلَى الْفَلَاحِ، اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللَّهُ" ثُمَّ دَعَانِي حِينَ قَضَيْتُ التَّأْذِينَ، فَأَعْطَانِي صُرَّةً فِيهَا شَيْءٌ مِنْ فضَّة، ثُمَّ وَضَعَ يَدَهُ عَلَى نَاصِيَةِ أَبِي مَحْذُورَةَ، ثُمَّ أَمَرَّهَا عَلَى وَجْهِهِ، ثُمَّ عَلَى ثَدْيَيْهِ، ثُمَّ عَلَى كَبِدِهِ، ثُمَّ بَلَغَتْ يَدُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُرَّةَ أَبِي مَحْذُورَةَ، ثُمَّ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ فَقُلْتُ: يَا رَسُولَ اللهِ أَمَرْتَنِي بِالتَّأْذِينِ بِمَكَّةَ قَالَ: "نَعَمْ قَدْ أَمَرْتُكَ" فَذَهَبَ كُلُّ شَيْءٍ كَانَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ كَرَاهِيَةٍ، وَعَادَ ذَلِكَ كُلُّهُ مَحَبَّةً لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَدِمْتُ عَلَى عَتَّابِ بْنِ أَسِيدٍ عَامِلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمَكَّةَ، فَأَذَّنْتُ مَعَهُ بِالصَّلَاةِ عَنْ أَمْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ق,د,ت,ن)', 'അബൂമഹ്ദൂറ(റ): ഞാൻ ഒരു സംഘത്തോടൊപ്പം പുറപ്പെട്ടു. വഴിയുടെ കുറച്ചു ഭാഗം കഴിഞ്ഞപ്പോൾ നബി(സ)യുടെ അടുത്തു വെച്ച് തന്റെ മുഅദ്ദിൻ ബാങ്കു വിളിച്ചു. ബാങ്കു വിളി കേട്ടിട്ടും ഞങ്ങൾ അതവഗണിച്ചു കൊണ്ട് നടന്നു. മുഅദ്ദിനെ അനുകരിച്ച് കളിയാക്കിക്കൊണ്ട് ഞങ്ങൾ ശബ്ദം വെച്ചു. അത് നബി(സ) കേട്ടു. ഞങ്ങളുടെ അടുത്തേക്കു കുറച്ചാളുകളെ പറഞ്ഞയച്ചു. അവർ ഞങ്ങളെ നബി(സ)യുടെ മുമ്പിലെത്തിച്ചു. "നിങ്ങളിൽ നിന്ന് ആരുടെ ഉച്ചത്തിലുള്ള ശബ്ദമാണ് ഞാൻ കേട്ടത്?" അവരെല്ലാം എന്നെ ചൂണ്ടിക്കാണിച്ചു. അവർ പറഞ്ഞത് സത്യമായിരുന്നു. എന്നെ അവിടെ നിറുത്തി മറ്റുള്ളവരെ പറഞ്ഞയച്ചു. നബി(സ) എന്നോട് പറഞ്ഞു: "നീ എഴുന്നേറ്റ് ബാങ്ക് വിളിക്കുക." ഞാൻ എഴുന്നേറ്റു നിന്നു. നബി(സ)യുടെ മുമ്പിൽ ഞാൻ നിന്നു. നബി(സ) എനിക്ക് ബാങ്കിന്റെ വചനങ്ങൾ ഇപ്രകാരം പറഞ്ഞുതന്നു: "അല്ലാഹു അക്ബർ അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ അശ്ഹദു അൻലാഇലാഹ ഇല്ലല്ലാഹു,അശ്ഹദു അൻലാഇലാഹ ഇല്ലല്ലാഹു, അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാ, അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാ എന്നു നീ പറയുക. ശേഷം മടക്കിപ്പറയുകയും ശബ്ദം നീട്ടിപ്പറയുകയും ചെയ്യുക. എന്നിട്ട് തിരുമേനി(സ) പറഞ്ഞു: നീ ഇപ്രകാരം പറയുക: അശ്ഹദു അൻലാഇലാഹ ഇല്ലല്ലാഹു,അശ്ഹദു അൻലാഇലാഹ ഇല്ലല്ലാഹു, അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാഹ്, അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാഹ്, ഹയ്യഅലസ്സ്വലാത്ത്, ഹയ്യഅലസ്സ്വലാത്ത്, ഹയ്യഅലൽ ഫലാഹ്, ഹയ്യഅലൽ ഫലാഹ്, അല്ലാഹു അക്ബർ, അല്ലാഹു അക്ബർ, ലാഇലാഹ ഇല്ലല്ലാഹ്." ബാങ്ക് വിളി കഴിഞ്ഞപ്പോൾ എന്നെ വിളിച്ച് വെള്ളി നാണയങ്ങളുടെ ഒരു കിഴി തന്നു. പിന്നീട് നബി(സ) തന്റെ കൈകൾ എന്റെ മൂർദ്ദാവിൽ വെച്ചു. ശേഷം മുഖത്തിലൂടെയും മാറിടത്തിലൂടെയും കരളിന്റെ മേലും പൊക്കിളിന്മേലും കൈ നടത്തി. തുടർന്ന് നബി(സ) പറഞ്ഞു: "നിനക്കും നിന്റെ മേലും അല്ലാഹു അഭിവൃദ്ധി നൽകട്ടെ." ഞാൻ നബി(സ)യോടു ചോദിച്ചു: പ്രവാചകരെ, താങ്കൾ മക്കയിൽ വെച്ച് ബാങ്ക് വിളിക്കാൻ എന്നോട് കൽപിക്കുന്നുവേ? നബി(സ) പറഞ്ഞു: "അതെ, ഞാൻ അപ്രകാരം കൽപിക്കുന്നു." അപ്പോൾ നബിയോടുണ്ടായിരുന്ന എന്റെ എല്ലാ വെറുപ്പും നീങ്ങുകയും അതെല്ലാം നബി(സ)യോടുള്ള സ്നേഹമായി മാറുകയും ചെയ്തു. അങ്ങനെ മക്കയിലെ നബി(സ)യുടെ ഗവർണറായിരുന്ന അത്താബുബ്നു അസീദിന്റെ അടുത്തേക്കു ഞാൻ പോവുകയും നബി(സ)യുടെ കൽപന പ്രകാരം ഞാൻ ബാങ്കു വിളിക്കുകയും ചെയ്തു. (ബു,മു,ദ,തു,ന)', 'أَبِي مَحْذُورَةَ', 'അബൂമഹ്ദൂറ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 307, 308, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
